// KC-CLUB-KUECHENTERROR (2.14.0, Wunsch Hansi): Fragen aus dem professionellen Küchenalltag.
// Aufbau: id (fest, nie ändern oder neu vergeben – laufende Partien merken sich die id), f = Frage, r = richtige Antwort,
// x = drei falsche Antworten, e = kurze Erklärung (wird nach der Frage gezeigt).
// Neue Fragen nur HINTEN anfügen (nächste freie id). Die Server-Kopie supabase/functions/kc-club/kt-fragen.js muss gleich sein
// (node tools/kuechenterror/server-kopie.mjs) – der Vertragstest prüft das.
export const KT_FRAGEN = [
  { id: "k001", f: "Was bedeutet „blanchieren“?", r: "Kurz in sprudelnd kochendem Wasser garen und sofort in Eiswasser abschrecken", x: ["Bei schwacher Hitze in Fett glasig dünsten, ohne dass es Farbe annimmt", "Mit starker Oberhitze überbacken, bis sich eine goldbraune Kruste bildet", "Lange in wenig Flüssigkeit zugedeckt schmoren und danach im Ofen trocknen lassen"], e: "Blanchieren erhält Farbe und Biss, stoppt Enzyme (besser haltbar) und erleichtert z. B. das Häuten von Tomaten." },
  { id: "k002", f: "Was ist Romanesco?", r: "Eine Blumenkohl-Sorte – oft als Kreuzung aus Blumenkohl und Brokkoli bezeichnet", x: ["Eine Kreuzung aus Weißkohl und Grünkohl, vor allem in Norditalien angebaut", "Eine Kreuzung aus Kohlrabi und Wirsing mit besonders zarten, gelben Blättern", "Eine italienische Artischockensorte mit spitzen, grünen Blütenblättern in Spiralform"], e: "Botanisch gehört Romanesco zum Blumenkohl (Brassica oleracea) – bekannt für seine spiralförmigen, spitzen Röschen." },
  { id: "k003", f: "Zu welcher Pflanzenfamilie gehört die Tomate – die Grundlage für Tomatenmark?", r: "Nachtschattengewächse", x: ["Kürbisgewächse", "Schmetterlingsblütler", "Kreuzblütler"], e: "Wie Kartoffel, Paprika und Aubergine gehört die Tomate zu den Nachtschattengewächsen." },
  { id: "k004", f: "Was ist ein Chateaubriand?", r: "Ein doppelt dickes Steak aus dem Mittelstück des Rinderfilets", x: ["Ein kräftiger Rotwein aus dem Bordeaux, benannt nach einem Schloss", "Ein Rumpsteak mit breitem Fettrand aus dem flachen Roastbeef", "Ein im Ganzen gebratener Kalbsrücken mit Kräuterkruste und Jus"], e: "Ca. 300–400 g aus dem Filet-Mittelstück, benannt nach dem Schriftsteller François-René de Chateaubriand. Meist für 2 Personen." },
  { id: "k005", f: "Was ist Mirepoix?", r: "Röstgemüse aus Zwiebel, Karotte und Knollensellerie", x: ["Eine Kräutermischung aus Dill, Kerbel und Estragon für Fisch", "Eine kalte Eiersauce mit Kapern und Essiggurken", "Ein Teig für Pasteten aus Mehl, Schmalz und Wasser"], e: "Klassisch 2 Teile Zwiebel, 1 Teil Karotte, 1 Teil Sellerie – Grundlage für Fonds, Saucen und Schmorgerichte." },
  { id: "k006", f: "Welche Aufgaben hat der Garde-Manger?", r: "Kalte Küche: Vorspeisen, Salate, Pasteten und Terrinen", x: ["Saucen, Fonds und die dazugehörigen Fleischgerichte", "Desserts, Backwaren, Eis und süße Garnituren", "Gemüse, Beilagen, Suppen und Eierspeisen am Herd"], e: "Der „Bewahrer der Speisen“ ist auch für Kühlräume und Vorräte verantwortlich. Dazu kommt das Vorbereiten von Fleisch und Fisch." },
  { id: "k007", f: "Wofür ist der Saucier in der Küchenbrigade zuständig?", r: "Saucen, Fonds und meist auch die Fleischgerichte", x: ["Desserts, Patisserie und das Speiseeis", "Fischgerichte samt Fischfonds und Fischsaucen", "Einkauf, Lager und die Kontrolle der Lieferungen"], e: "Der Saucier gilt in der klassischen Brigade als einer der wichtigsten Posten." },
  { id: "k008", f: "Wofür ist der Entremetier zuständig?", r: "Gemüse, Beilagen, Suppen und Eierspeisen", x: ["Braten, Grillgerichte und Frittiertes", "Kalte Platten, Pasteten, Terrinen und Salate", "Saucen, Fonds und die Fleischgerichte"], e: "Oft aufgeteilt in Légumier (Gemüse) und Potager (Suppen)." },
  { id: "k009", f: "Wer ist in der Küchenbrigade der „Tournant“?", r: "Der Springer – er vertritt die Postenchefs, wo er gebraucht wird", x: ["Der Spüler – er kümmert sich um Töpfe, Pfannen und Geschirr", "Der Küchenchef – er leitet die gesamte Brigade und den Einkauf", "Der Lehrling im ersten Jahr, der alle Posten der Reihe nach durchläuft"], e: "Der Tournant (Springer) muss alle Posten beherrschen." },
  { id: "k010", f: "Was ist ein Commis?", r: "Ein Jungkoch, der einem Chef de Partie zuarbeitet", x: ["Der Stellvertreter des Küchenchefs, der die Brigade leitet", "Der Chef der kalten Küche mit Pasteten und Terrinen", "Ein Kellner im Restaurant, der die Teller abräumt"], e: "Commis de cuisine = Jungkoch, meist nach der Ausbildung." },
  { id: "k011", f: "Wer ist der Sous-Chef?", r: "Der Stellvertreter des Küchenchefs", x: ["Der Saucenkoch der Brigade", "Der Spüler im Unterbau der Küche", "Der Chef der Patisserie im Untergeschoss"], e: "Sous = unter: Er leitet die Küche, wenn der Küchenchef nicht da ist." },
  { id: "k012", f: "Was macht der Poissonnier?", r: "Fischgerichte und die dazugehörigen Saucen", x: ["Geflügelgerichte und die passenden Füllungen", "Brot, Brötchen und Blätterteiggebäck", "Vorspeisen, Salate und kalte Platten"], e: "Poisson = Fisch." },
  { id: "k013", f: "Was macht der Rôtisseur?", r: "Braten, Grillgerichte und Frittiertes", x: ["Desserts, Eis und Gebäck", "Suppen, Eintöpfe und Einlagen", "Kalte Saucen, Dressings und Marinaden"], e: "In großen Brigaden gibt es zusätzlich den Grillardin (Grill) und den Friturier (Fritteuse)." },
  { id: "k014", f: "Was macht der Plongeur?", r: "Er spült Töpfe, Pfannen und Geschirr", x: ["Er taucht lebende Fische aus dem Becken", "Er bereitet die Fonds und Brühen zu", "Er portioniert Fleisch für den Service"], e: "Ohne Plongeur steht jede Küche still!" },
  { id: "k015", f: "Wer gilt als Begründer der klassischen Küchenbrigade?", r: "Auguste Escoffier", x: ["Paul Bocuse", "Marie-Antoine Carême", "Eckart Witzigmann"], e: "Escoffier organisierte Ende des 19. Jahrhunderts die Küche in feste Posten." },
  { id: "k016", f: "Was bedeutet „Mise en place“?", r: "Alles für den Service vorbereitet und griffbereit an seinem Platz", x: ["Das Anrichten der fertigen Speisen auf dem vorgewärmten Teller", "Das Abräumen und Reinigen der Posten nach dem Service", "Die Tischordnung und die Platzierung der Gäste im Restaurant"], e: "Gute Mise en place ist die halbe Miete im Stress des Services." },
  { id: "k017", f: "Was ist in der Küche „der Pass“?", r: "Die Ausgabe, an der Teller kontrolliert und an den Service gehen", x: ["Ein feines Durchschlagsieb zum Passieren von Saucen und Fonds", "Der Lieferanteneingang, an dem die Ware angenommen wird", "Die gesetzlich vorgeschriebene Pause des Küchenpersonals im Dienst"], e: "Am Pass steht meist der Küchenchef und ruft die Bons aus." },
  { id: "k018", f: "Was ist ein „Bon“?", r: "Der Bestellzettel vom Service an die Küche", x: ["Ein Gutschein für Stammgäste des Restaurants", "Ein kleines Gebäck zum Kaffee", "Die Rechnung, die der Gast am Tisch bekommt"], e: "Bon = Bestellung – „Bon kommt!“" },
  { id: "k019", f: "Was ist ein Amuse-Bouche?", r: "Ein kleiner Gruß aus der Küche vor dem Menü", x: ["Das Hauptgericht eines klassischen Menüs", "Ein Digestif nach dem Essen, oft ein Kräuterlikör", "Ein Brotkorb mit gesalzener Butter"], e: "Amuse-bouche = „erfreut den Mund“, ein bis zwei Bissen." },
  { id: "k020", f: "Was bedeutet „à la minute“?", r: "Erst auf Bestellung frisch zubereitet", x: ["In genau einer Minute gegart", "Vorgekocht und im Bain-Marie warm gehalten", "Nur mittags auf der Karte erhältlich"], e: "Typisch für Kurzgebratenes und Fisch." },
  { id: "k021", f: "Was ist ein brauner Kalbsfond?", r: "Fond aus angerösteten Kalbsknochen, Röstgemüse und Tomatenmark", x: ["Eine mit Mehl gebundene Bratensauce aus Schweinebraten und Zwiebeln", "Ein Brühwürfel aus getrocknetem Kalbfleisch, Salz und Hefeextrakt", "Eine helle Kalbsbrühe aus ungerösteten Knochen, mit Sahne verfeinert"], e: "Knochen und Gemüse werden angeröstet, abgelöscht und stundenlang ausgekocht – Basis vieler Saucen." },
  { id: "k022", f: "Welche Sauce gehört NICHT zu den fünf Grundsaucen nach Escoffier?", r: "Remoulade", x: ["Béchamel", "Velouté", "Hollandaise"], e: "Die fünf: Béchamel, Velouté, Espagnole, Hollandaise und Tomatensauce." },
  { id: "k023", f: "Woraus besteht eine Béchamelsauce?", r: "Milch und helle Mehlschwitze", x: ["Fischfond und süße Sahne", "Eigelb und geklärte Butter", "Kalbsfond und passierte Tomaten"], e: "Mit Zwiebel, Lorbeer und Nelke (gespickte Zwiebel) und Muskat abgeschmeckt." },
  { id: "k024", f: "Woraus besteht eine Sauce Hollandaise?", r: "Warm aufgeschlagenem Eigelb und geklärter Butter", x: ["Mayonnaise mit Senf und frischem Zitronensaft", "Milch und heller Mehlschwitze mit etwas Muskat", "Kalt geschlagener Sahne und geriebenem Bergkäse"], e: "Eine warme, aufgeschlagene Emulsion – nicht zu heiß, sonst gerinnt das Eigelb." },
  { id: "k025", f: "Welches Kraut ist typisch für die Sauce Béarnaise?", r: "Estragon", x: ["Basilikum", "Dill", "Liebstöckel"], e: "Béarnaise = Hollandaise mit Reduktion aus Essig, Schalotten, Pfeffer und Estragon, dazu Kerbel." },
  { id: "k026", f: "Was ist eine Velouté?", r: "Heller Fond, mit heller Mehlschwitze gebunden", x: ["Eine kalte Gemüsesuppe aus Gurken und Paprika", "Ein Samtstoff zum Einschlagen von Servietten", "Eine Schokoladensauce mit Sahne und Butter"], e: "Velouté = samtig. Je nach Fond: Kalbs-, Geflügel- oder Fischvelouté." },
  { id: "k027", f: "Was ist eine Roux?", r: "Eine Mehlschwitze aus Fett und Mehl", x: ["Ein milder Rotweinessig aus Burgund", "Ein Röstgemüse aus Zwiebeln und Karotten", "Eine scharfe Sauce aus gerösteter Paprika"], e: "Hell, blond oder braun – je nachdem, wie lange sie geröstet wird." },
  { id: "k028", f: "Was ist eine Liaison (Legierung)?", r: "Eigelb und Sahne zum Binden und Verfeinern", x: ["Butter und Mehl roh verknetet zum Binden", "Stärke in kaltem Wasser angerührt zum Andicken", "Blattgelatine in Weißwein aufgelöst zum Stocken"], e: "Nicht mehr kochen lassen, sonst gerinnt das Eigelb." },
  { id: "k029", f: "Was ist Beurre manié?", r: "Roh verknetete Butter und Mehl zum schnellen Binden", x: ["Gebräunte Butter, die nussig duftet und Farbe hat", "Geklärte Butter ohne Wasser und Milcheiweiß", "Kräuterbutter mit Petersilie, Knoblauch und Zitrone"], e: "Mehlbutter – in kleinen Flocken in die kochende Sauce rühren." },
  { id: "k030", f: "Was bedeutet „eine Sauce montieren“?", r: "Kalte Butterstücke einschwenken, um sie zu binden und zu verfeinern", x: ["Die Sauce durch ein feines Sieb oder ein Passiertuch passieren", "Die Sauce mit heller Mehlschwitze oder Stärke abbinden", "Die Sauce mit dem Löffel dekorativ auf dem Teller verteilen"], e: "Die Sauce darf danach nicht mehr kochen, sonst trennt sich die Butter." },
  { id: "k031", f: "Was bedeutet „deglacieren“?", r: "Den Bratensatz mit Flüssigkeit ablöschen und lösen", x: ["Eis und Reif aus dem Tiefkühler entfernen und abtauen", "Gemüse mit Butter und Zucker glänzend glasieren", "Fett von der Oberfläche einer Sauce abschöpfen"], e: "Mit Wein, Fond oder Wasser – der Bratensatz bringt viel Geschmack in die Sauce." },
  { id: "k032", f: "Was bedeutet „pochieren“?", r: "In Flüssigkeit knapp unter dem Siedepunkt garziehen lassen", x: ["In sprudelnd kochendem Salzwasser kräftig durchkochen", "In heißem Fett bei etwa 170 °C goldbraun ausbacken", "Unter dem Grill oder Salamander von oben kräftig bräunen"], e: "Etwa 75–95 °C – schonend, z. B. für Eier, Fisch oder Klöße." },
  { id: "k033", f: "Was bedeutet „sautieren“?", r: "In wenig heißem Fett kurz braten und dabei schwenken", x: ["Lange im geschlossenen Bräter im Ofen schmoren", "In reichlich Salzwasser weich kochen und abgießen", "Mit Zucker in der Pfanne langsam goldbraun karamellisieren"], e: "Von sauter = springen. Dafür gibt es die Sauteuse." },
  { id: "k034", f: "Was bedeutet „confieren“?", r: "Langsam in Fett bei niedriger Temperatur garen", x: ["In Zuckersirup einkochen, bis die Frucht glasig ist", "Mit Gelee überziehen und kalt stellen", "Im Wasserbad mit Eis schnell herunterkühlen"], e: "Klassisch: Entenkeulen im eigenen Fett (Confit de canard)." },
  { id: "k035", f: "Was bedeutet „sous-vide“ garen?", r: "Vakuumiert bei genau eingestellter Temperatur im Wasserbad garen", x: ["Ohne Deckel im offenen Topf bei starker Hitze kochen", "Unter Druck im Schnellkochtopf bei etwa 120 °C garen", "In der Mikrowelle in einem abgedeckten Gefäß aus Glas langsam erhitzen"], e: "Sous vide = unter Vakuum. Sehr gleichmäßige Garstufe. Gegart wird meist bei niedriger Temperatur." },
  { id: "k036", f: "Was bedeutet „gratinieren“?", r: "Mit starker Oberhitze überbacken, bis eine braune Kruste entsteht", x: ["In Butter bei schwacher Hitze dünsten, ohne Farbe zu geben", "In gleichmäßige Würfel von etwa einem Zentimeter Kantenlänge schneiden", "Mit Mehl bestäuben und anschließend in Ei und Bröseln wenden"], e: "Gerne unter dem Salamander." },
  { id: "k037", f: "Was ist ein Salamander in der Profiküche?", r: "Ein Oberhitzegerät zum Gratinieren und Überbacken", x: ["Ein Gemüsehobel mit verstellbarem Messer", "Ein Kühlschrank speziell für frischen Fisch auf Eis", "Ein Schneidebrett aus Holz für rohes Fleisch"], e: "Die Hitze kommt nur von oben – ideal für Krusten." },
  { id: "k038", f: "Was bedeutet „parieren“?", r: "Fleisch von Sehnen, Häuten und überschüssigem Fett befreien", x: ["Fleisch mit dem Plattiereisen gleichmäßig flach klopfen", "Fleisch mit dünnen Speckscheiben belegen oder umwickeln", "Fleisch vor dem Braten mit Salz, Pfeffer und frischen Kräutern würzen"], e: "Die Abschnitte (Parüren) wandern in Fonds und Saucen." },
  { id: "k039", f: "Was bedeutet „plattieren“?", r: "Fleisch flach klopfen", x: ["Fleisch auf Platten anrichten", "Fleisch in Scheiben schneiden", "Fleisch panieren"], e: "Mit dem Plattiereisen – für Schnitzel und Rouladen." },
  { id: "k040", f: "Was bedeutet „bardieren“?", r: "Fleisch oder Geflügel mit Speckscheiben belegen oder umwickeln", x: ["Speckstreifen mit der Spicknadel ins magere Fleisch ziehen", "Fleisch über Nacht in dunklem Bier mit Zwiebeln marinieren", "Fleisch oder Geflügel am Drehspieß über offenem Feuer grillen"], e: "Schützt mageres Fleisch vor dem Austrocknen." },
  { id: "k041", f: "Was bedeutet „spicken“?", r: "Speckstreifen mit der Spicknadel ins Fleisch ziehen", x: ["Fleisch oder Geflügel mit Speckscheiben umwickeln", "Fleisch vor dem Garen rundherum mit Gewürznelken bestecken", "Fleisch mit der Gabel rundum mehrmals einstechen"], e: "Klassisch bei magerem Wild wie Rehrücken." },
  { id: "k042", f: "Was bedeutet es, Geflügel zu „dressieren“?", r: "Es mit Küchengarn in Form binden, damit es gleichmäßig gart", x: ["Es über Nacht in einer Salatsauce aus Öl und Essig marinieren", "Es vollständig entbeinen und anschließend füllen", "Es rupfen und die restlichen Federkiele abflämmen"], e: "Keulen und Flügel liegen dann eng am Körper." },
  { id: "k043", f: "Was ist eine Brunoise?", r: "Sehr feine Gemüsewürfel von etwa 1–2 mm", x: ["Feine Gemüsestreifen von etwa 4–5 cm Länge", "Dünne Gemüsescheiben von etwa 2–3 mm", "Grob gehacktes Gemüse für Fonds und Saucen"], e: "Gleichmäßig geschnitten – ein Klassiker der Kochprüfung." },
  { id: "k044", f: "Was ist eine Julienne?", r: "Feine Streifen, etwa streichholzdünn", x: ["Feine Würfel von etwa 1–2 mm Kantenlänge", "Gedrehte Spiralen aus Zucchini", "Kleine Kugeln, mit dem Ausstecher geformt"], e: "Etwa 1–2 mm dick und 4–5 cm lang." },
  { id: "k045", f: "Was ist eine Chiffonade?", r: "Fein geschnittene Streifen von Blattgemüse oder Kräutern", x: ["Ein feines Seidentuch zum Passieren von Fonds und Saucen", "Ein luftiger Kuchen aus Eischnee, Zucker und Speisestärke", "Ein biegsames Fischmesser mit dünner, langer Klinge"], e: "Z. B. Basilikum aufrollen und quer in feine Streifen schneiden." },
  { id: "k046", f: "Was ist eine Tomaten-Concassée?", r: "Gehäutete, entkernte und gewürfelte Tomaten", x: ["Dreifach konzentriertes Tomatenmark aus der Tube", "Getrocknete Tomaten, in Olivenöl eingelegt", "Passierte Tomatensuppe mit Basilikum"], e: "Concasser = grob hacken." },
  { id: "k047", f: "Wie viele Flächen hat klassisch tourniertes Gemüse?", r: "Sieben Flächen", x: ["Fünf Flächen", "Sechs Flächen", "Zwölf Flächen"], e: "Die Fässchenform mit sieben Flächen ist der Klassiker." },
  { id: "k048", f: "Was ist eine Duxelles?", r: "Fein gehackte, mit Schalotten trocken gedünstete Pilze", x: ["Eine grobe Entenpastete mit Pistazien im Teigmantel", "Ein doppelter Espresso mit einem Schuss Cognac", "Ein gesüßter Mürbeteig für Tartes und Törtchen"], e: "Z. B. für Beef Wellington." },
  { id: "k049", f: "Was gehört in ein klassisches Bouquet garni?", r: "Thymian, Lorbeer und Petersilienstängel – oft in Lauch gebunden", x: ["Zimt, Nelke und Sternanis – zusammen in ein Mulltuch eingeschlagen", "Rosmarin, Salbei und Lavendelblüten – mit Bindfaden gebunden", "Chili, Ingwer und Knoblauch – fein gehackt und angeschwitzt"], e: "Das Kräuterbündel wird mitgekocht und vor dem Servieren entfernt." },
  { id: "k050", f: "Welche Kräuter gehören zu den „Fines herbes“?", r: "Petersilie, Kerbel, Schnittlauch und Estragon", x: ["Rosmarin, Thymian, Bohnenkraut, Salbei und Oregano", "Dill, Koriander, Minze und Thai-Basilikum", "Lorbeer, Wacholder, Piment und Gewürznelke"], e: "Feine, zarte Kräuter – gerne für Omelette und Saucen." },
  { id: "k051", f: "Was ist Gremolata?", r: "Gehackte Petersilie mit Zitronenschale und Knoblauch", x: ["Ein gereifter italienischer Hartkäse aus Schafsmilch", "Gegrillte Polenta-Schnitten mit Rosmarin", "Eine Steinpilzsauce mit Sahne und Weißwein"], e: "Klassisch über Ossobuco gestreut." },
  { id: "k052", f: "Womit klärt man eine Consommé?", r: "Mit Klärfleisch aus magerem Hack, Eiweiß und Gemüse", x: ["Mit eingeweichter Blattgelatine und einem Schuss Essig", "Mit heller Mehlschwitze und etwas kaltem Wasser", "Mit süßer Sahne und einem Eigelb als Liaison"], e: "Das Eiweiß bindet beim Erhitzen die Trübstoffe – es entsteht eine glasklare Kraftbrühe." },
  { id: "k053", f: "Was ist ein Bain-Marie?", r: "Ein Wasserbad zum schonenden Garen oder Warmhalten", x: ["Ein Badezusatz aus grobem Meersalz zum Pökeln", "Ein würziger Fischsud mit Weißwein und Fenchel", "Ein gusseiserner Grillrost für den Holzkohlegrill"], e: "Benannt nach der Alchemistin Maria – ideal für Saucen und Terrinen." },
  { id: "k054", f: "Welche Kerntemperatur hat ein Rinderfilet „medium“ (rosa)?", r: "Etwa 55–58 °C", x: ["Etwa 40–42 °C", "Etwa 68–70 °C", "Etwa 78–80 °C"], e: "Rare ca. 48–52 °C, medium ca. 55–58 °C, well done ab ca. 65 °C." },
  { id: "k055", f: "Bei mindestens welcher Temperatur müssen warme Speisen heiß gehalten werden?", r: "65 °C", x: ["45 °C", "55 °C", "90 °C"], e: "Darunter können sich Keime schnell vermehren." },
  { id: "k056", f: "Wie kalt muss Hackfleisch höchstens gelagert werden?", r: "+2 °C", x: ["+7 °C", "+10 °C", "+12 °C"], e: "Hackfleisch ist besonders empfindlich und gehört ganz nach unten in die Kühlung." },
  { id: "k057", f: "Bei welcher Temperatur wird frischer Fisch am besten gelagert?", r: "Bei 0 bis +2 °C, am besten auf Eis", x: ["Bei +8 bis +10 °C im Kühlhaus", "Bei Raumtemperatur, gut abgedeckt", "Bei +5 bis +7 °C, am besten in Wasser"], e: "Fisch verdirbt sehr schnell – Eis mit Abfluss ist ideal." },
  { id: "k058", f: "Welche Temperatur brauchen Tiefkühlprodukte mindestens?", r: "−18 °C", x: ["−5 °C", "−10 °C", "0 °C"], e: "Die Kühlkette darf nicht unterbrochen werden." },
  { id: "k059", f: "Was bedeutet FIFO im Lager?", r: "First in, first out – was zuerst kam, wird zuerst verbraucht", x: ["Fisch immer frisch ordern – täglich statt wöchentlich bestellen", "Fix, intern, fertig, offen – der Status einer Bestellung", "Frisch ins Fach, ohne Ordnung – Ware dort lagern, wo Platz ist"], e: "Neue Ware nach hinten, ältere nach vorne." },
  { id: "k060", f: "Wofür steht HACCP?", r: "Gefahrenanalyse und kritische Kontrollpunkte", x: ["Hygienischer Arbeitsplatz mit Chlor-Pflege", "Handbuch für Allergene", "Hauptküche, Ausgabe, Café, Cantina, Patisserie"], e: "Hazard Analysis and Critical Control Points – das Eigenkontrollsystem jeder Küche." },
  { id: "k061", f: "Wie viele Hauptallergene müssen in der EU gekennzeichnet werden?", r: "14", x: ["7", "10", "21"], e: "U. a. Gluten, Krebstiere, Eier, Fisch, Erdnüsse, Soja, Milch, Schalenfrüchte, Sellerie, Senf, Sesam, Sulfite, Lupinen, Weichtiere." },
  { id: "k062", f: "Bei welcher Temperatur vermehren sich die meisten Keime am schnellsten?", r: "Bei etwa 30–40 °C", x: ["Bei etwa 0–5 °C", "Bei etwa 70–80 °C", "Bei etwa −18 °C"], e: "Nahe der Körpertemperatur fühlen sich Bakterien am wohlsten – darum schnell abkühlen!" },
  { id: "k063", f: "Was ist die Maillard-Reaktion?", r: "Die Bräunung von Zucker und Eiweiß beim Braten", x: ["Das Karamellisieren von reinem Zucker ohne Eiweiß", "Das Gerinnen von Eiweiß bei etwa 60 °C", "Das Verkleistern von Stärke in heißer Flüssigkeit"], e: "Benannt nach dem Chemiker Louis-Camille Maillard – darum Fleisch scharf anbraten. Sie bringt die typischen Röstaromen." },
  { id: "k064", f: "Warum geliert Gelatine nicht mit frischer Ananas?", r: "Das Enzym Bromelain spaltet die Gelatine", x: ["Ananas enthält zu viel Fruchtzucker zum Gelieren", "Die Fruchtsäure der Ananas löst die Gelatine auf", "Ananas ist zu kalt, wenn sie aus der Kühlung kommt"], e: "Gekochte Ananas aus der Dose geht – das Enzym ist dann zerstört. Ähnlich: Kiwi, Papaya." },
  { id: "k065", f: "Was ist Agar-Agar?", r: "Ein pflanzliches Geliermittel aus Algen", x: ["Eine indische Gewürzmischung mit Kardamom", "Ein kalorienfreier Zuckerersatz aus Stevia", "Ein Sauerteig aus Reismehl"], e: "Vegane Alternative zu Gelatine – muss aufgekocht werden." },
  { id: "k066", f: "Was unterscheidet die Crème brûlée?", r: "Ihre Zuckerdecke wird obenauf karamellisiert (abgeflämmt)", x: ["Sie wird nach dem Garen aus der Form auf den Teller gestürzt", "Sie wird mit Gelatine gebunden und kalt gestockt", "Sie wird gefroren serviert, ähnlich wie ein Parfait"], e: "Brûlée = verbrannt. Die Crème caramel dagegen wird gestürzt." },
  { id: "k067", f: "Was ist eine Sabayon bzw. Zabaione?", r: "Warm aufgeschlagener Weinschaum aus Eigelb, Zucker und Wein", x: ["Ein süßer Hefezopf mit Rosinen, Mandeln und Hagelzucker obenauf", "Ein Fruchtsorbet aus Zitronen und Prosecco", "Eine kalte Kräutersauce aus Joghurt, Gurke und Dill"], e: "In Italien klassisch mit Marsala." },
  { id: "k068", f: "Was ist Pâte à choux?", r: "Brandteig – zum Beispiel für Windbeutel und Eclairs", x: ["Blätterteig – zum Beispiel für Schweineohren und Pasteten", "Mürbeteig – zum Beispiel für Tarteböden und Plätzchen", "Hefeteig – zum Beispiel für Zopf und Berliner"], e: "Der Teig wird im Topf „abgebrannt“, dann kommen die Eier hinein." },
  { id: "k069", f: "Wofür steht die Mürbeteig-Regel „1-2-3“?", r: "1 Teil Zucker, 2 Teile Fett, 3 Teile Mehl", x: ["1 Ei, 2 Tassen Milch, 3 Löffel Mehl", "1 Stunde kühlen, 2 mm ausrollen, 3 Minuten backen", "1 Teil Salz, 2 Teile Wasser, 3 Teile Mehl"], e: "Dazu oft etwas Ei und eine Prise Salz – und kühl verarbeiten." },
  { id: "k070", f: "Was bedeutet „tourieren“?", r: "Teig mit eingeschlagenem Fett mehrmals ausrollen und falten", x: ["Gemüse in gleichmäßige Fässchenform mit sieben Flächen schneiden", "Fleisch am Spieß langsam über dem Feuer drehen", "Eine Torte mit Spritzbeutel und Sahnetupfen dekorieren"], e: "So entstehen die vielen Schichten von Blätter- und Plunderteig." },
  { id: "k071", f: "Was ist eine Ganache?", r: "Eine Creme aus Schokolade und Sahne", x: ["Ein Baiser aus Eiweiß und Zucker", "Ein Fruchtgelee aus Quitten und Äpfeln", "Eine Vanillesauce aus Milch und Eigelb"], e: "Für Pralinen, Tortenfüllungen und Glasuren." },
  { id: "k072", f: "Was bedeutet „zur Rose abziehen“?", r: "Eine Eigelb-Milch-Masse unter Rühren erhitzen, bis sie leicht bindet", x: ["Rosenblätter in Zuckersirup kochen und anschließend auf Gittern kandieren", "Eine Torte mit gespritzten Rosen aus Buttercreme verzieren", "Fleisch rosa braten und vor dem Anschneiden ruhen lassen"], e: "Pustet man auf den Kochlöffel, zeigt sich ein Muster wie eine Rose. Kochen = Rührei! Das geschieht bei ca. 82–85 °C." },
  { id: "k073", f: "Was ist ein Parfait?", r: "Eine halbgefrorene Masse aus Eigelb, Zucker und geschlagener Sahne", x: ["Ein Sorbet aus Fruchtsaft und Zuckersirup, in der Eismaschine gerührt", "Ein trockener, leichter Weißwein aus dem Süden Frankreichs", "Eine warme Schokoladensauce aus Kuvertüre, Sahne und Butter"], e: "Durch die Luft in der Sahne bleibt es zart und schnittfest. Sie wird ohne Rühren gefroren." },
  { id: "k074", f: "Was unterscheidet ein Sorbet von Speiseeis?", r: "Sorbet enthält keine Milch und keine Sahne", x: ["Sorbet wird warm oder lauwarm serviert", "Sorbet enthält immer einen Schuss Alkohol", "Sorbet wird mit Gelatine gebunden und gestürzt"], e: "Fruchtmark oder Saft, Zucker und Wasser." },
  { id: "k075", f: "Was sind Tournedos?", r: "Kleine, dicke Steaks aus dem Rinderfilet-Mittelstück", x: ["Gedrehte Nudeln aus Hartweizengrieß, Ei und etwas Salz", "Kartoffeln in Fässchenform, in Butter gebraten", "Gefüllte Teigtaschen aus Nudelteig mit Ricotta"], e: "Oft mit einer Speckscheibe umwickelt – klassisch: Tournedos Rossini." },
  { id: "k076", f: "Woher stammt das Entrecôte?", r: "Aus dem Zwischenrippenstück vom Rind", x: ["Aus der Oberschale der Keule", "Aus dem dicken Bug der Schulter", "Aus der Nachbrust, nahe dem Brustbein"], e: "Entre côtes = zwischen den Rippen – schön marmoriert." },
  { id: "k077", f: "Aus welchem Teil des Rindes kommt der Tafelspitz?", r: "Aus der Hüfte", x: ["Aus der Schulter", "Aus der Brust", "Aus dem Hals"], e: "Gekocht ein Wiener Klassiker – mit Apfelkren und Schnittlauchsauce." },
  { id: "k078", f: "Was ist Ossobuco?", r: "Geschmorte Kalbshaxe in Scheiben", x: ["Ein geröstetes Knochenmark-Brot", "Eine Pasta mit Fleisch vom Knochen", "Ein Bohneneintopf mit Speck"], e: "Osso buco = Knochen mit Loch – serviert mit Gremolata." },
  { id: "k079", f: "Was ist Saltimbocca?", r: "Kalbsschnitzel mit Salbei und Rohschinken", x: ["Ein Fischgericht mit Kapern und Zitrone", "Eine Pizza mit Salami und Peperoni", "Ein Mandelgebäck aus Sizilien mit Honig"], e: "Salta in bocca = springt in den Mund." },
  { id: "k080", f: "Aus welchem Fleisch ist ein echtes Wiener Schnitzel?", r: "Kalbfleisch", x: ["Schweinefleisch", "Putenfleisch", "Rindfleisch"], e: "Aus Schwein heißt es „Schnitzel Wiener Art“." },
  { id: "k081", f: "In welcher Reihenfolge paniert man klassisch?", r: "Mehl, Ei, Semmelbrösel", x: ["Ei, Mehl, Semmelbrösel", "Semmelbrösel, Ei, Mehl", "Mehl, Semmelbrösel, Ei"], e: "Die „Wiener Panade“." },
  { id: "k082", f: "Was bedeutet „Pariser Art“?", r: "In Mehl und verquirltem Ei wenden und braten – ohne Brösel", x: ["Mit Sahnesauce und Käse im Ofen überbacken", "In Mehl, Ei und Semmelbröseln wenden und in Butterschmalz ausbacken", "Mit Weißwein abgelöscht und anschließend flambiert"], e: "Ergibt eine zarte, goldgelbe Eihülle." },
  { id: "k083", f: "Was bedeutet „Müllerin Art“ (à la meunière)?", r: "Fisch mehlieren, in Butter braten, mit brauner Butter und Zitrone", x: ["Fisch im Ganzen in einer Salzkruste im Ofen backen", "Fisch durch einen Bierteig ziehen und in heißem Öl goldbraun frittieren", "Fisch mit Schalotten und Speck in Rotwein schmoren"], e: "Die Müllerin hatte das Mehl immer zur Hand. Dazu kommt gehackte Petersilie." },
  { id: "k084", f: "Was ist für „Forelle blau“ entscheidend?", r: "Die Schleimhaut muss unverletzt bleiben, dann im Essigsud ziehen lassen", x: ["Der Fisch wird vor dem Garen mit blauer Lebensmittelfarbe gefärbt", "Der Fisch wird zusammen mit Rotkohl im geschlossenen Topf gegart", "Der Fisch muss vorher mindestens einen Tag tiefgefroren gewesen sein"], e: "Essig und Schleimschicht sorgen für die blaue Farbe." },
  { id: "k085", f: "Wie viele Filets liefert ein Plattfisch wie die Seezunge?", r: "Vier", x: ["Zwei", "Drei", "Sechs"], e: "Je zwei von der Ober- und der Unterseite." },
  { id: "k086", f: "Warum wird Hummer beim Kochen rot?", r: "Hitze löst den Farbstoff Astaxanthin von seinem Eiweiß", x: ["Das Blut des Hummers tritt beim Kochen aus und färbt den Panzer", "Das Salz im Kochwasser reagiert mit dem Kalk im Panzer", "Er wird traditionell mit Paprika im Sud gekocht"], e: "Im rohen Zustand ist das Astaxanthin an Eiweiß gebunden und wirkt blauschwarz. Dann zeigt sich der rote Farbstoff." },
  { id: "k087", f: "Echter Kaviar stammt vom …", r: "Stör", x: ["Lachs", "Seehasen", "Hering"], e: "Andere Fischrogen sind Kaviar-Ersatz, z. B. Lachs- oder Forellenkaviar." },
  { id: "k088", f: "Was ist Carpaccio im Original?", r: "Hauchdünne Scheiben vom rohen Rinderfilet", x: ["Gegrilltes Gemüse mit Olivenöl und Balsamico", "Ein Schmorgericht vom Kalb mit Weißwein", "Eine Pasta mit Speck, Ei und Pecorino"], e: "Erfunden in Harry’s Bar in Venedig, benannt nach dem Maler Carpaccio." },
  { id: "k089", f: "Was ist Ceviche?", r: "Roher Fisch, in Limettensaft „gegart“ – aus Peru", x: ["Ein luftgetrockneter Schinken aus Spanien", "Eine scharfe Bohnensuppe aus Mexiko mit Chili", "Ein argentinisches Rindersteak vom Holzkohlegrill"], e: "Die Säure verändert das Eiweiß ähnlich wie Hitze." },
  { id: "k090", f: "Welche Reissorte nimmt man für Risotto?", r: "Carnaroli oder Arborio", x: ["Basmati oder Patna", "Jasminreis oder Klebreis", "Parboiled Langkornreis"], e: "Rundkornreis gibt Stärke ab und macht das Risotto cremig." },
  { id: "k091", f: "Was sind Herzoginkartoffeln (Pommes duchesse)?", r: "Kartoffelmasse mit Eigelb und Butter, aufgespritzt und gebacken", x: ["In dünne Scheiben geschnittene, mit Sahne geschichtete Kartoffeln", "Bratkartoffeln mit Speck und Zwiebeln aus der Pfanne", "Kartoffelsalat, mit warmer Brühe und Essig angemacht"], e: "Die Masse ist auch die Basis für Kroketten." },
  { id: "k092", f: "Welche Kartoffeln nimmt man für Püree?", r: "Mehligkochende", x: ["Festkochende", "Neue Frühkartoffeln", "Süßkartoffeln"], e: "Mehligkochende zerfallen leicht und werden schön locker." },
  { id: "k093", f: "Warum frittiert man Pommes frites zweimal?", r: "Erst bei niedriger Temperatur garen, dann heiß knusprig ausbacken", x: ["Damit sie insgesamt weniger Fett aufnehmen und leichter verdaulich sind", "Damit sie nach dem Servieren länger warm bleiben", "Damit sie sich durch das zweite Bad schön gelb färben"], e: "Vorbacken etwa 140–160 °C, fertig backen etwa 170–175 °C." },
  { id: "k094", f: "Welche Höchsttemperatur empfiehlt man beim Frittieren von Kartoffeln wegen Acrylamid?", r: "175 °C", x: ["150 °C", "200 °C", "220 °C"], e: "„Vergolden statt verkohlen“." },
  { id: "k095", f: "Welches Fett eignet sich am besten zum scharfen Anbraten?", r: "Butterschmalz bzw. geklärte Butter", x: ["Normale Süßrahmbutter", "Kaltgepresstes Lein- oder Walnussöl", "Halbfettmargarine aus dem Becher"], e: "Ohne Milcheiweiß und Wasser verträgt das Fett hohe Temperaturen." },
  { id: "k096", f: "Was ist Beurre noisette?", r: "Nussbutter – Butter, gebräunt, bis sie nussig duftet", x: ["Butter, mit gerösteten und gehackten Haselnüssen verknetet", "Erdnussbutter aus gerösteten Erdnüssen", "Ungesalzene Süßrahmbutter aus der Normandie"], e: "Noisette = Haselnuss – wegen Farbe und Duft." },
  { id: "k097", f: "Was ist eine Beurre blanc?", r: "Eine Reduktion aus Schalotten, Wein und Essig, mit kalter Butter aufgeschlagen", x: ["Weiße, ungesalzene Butter aus Süßrahm, in Würfel geschnitten und gekühlt", "Eine Béchamel, zum Schluss mit reichlich Butter und Muskat verfeinert", "Ein flacher Butterkuchen vom Blech mit Mandeln und Zucker"], e: "Klassisch zu Fisch – nicht kochen lassen. Auf Deutsch: Weißwein-Buttersauce." },
  { id: "k098", f: "Was hält eine Mayonnaise als Emulgator zusammen?", r: "Das Lecithin im Eigelb", x: ["Das Salz in der Würzung", "Der Zucker im Senf", "Die Säure im Essig"], e: "Lecithin verbindet Öl und Wasser." },
  { id: "k099", f: "Welches Grundverhältnis hat eine klassische Vinaigrette?", r: "1 Teil Essig, 3 Teile Öl", x: ["1 Teil Öl, 3 Teile Essig", "Halb und halb", "1 Teil Essig, 10 Teile Öl"], e: "Dazu Salz, Pfeffer, oft Senf." },
  { id: "k100", f: "Was beschreibt „umami“?", r: "Die fünfte Geschmacksrichtung – herzhaft, fleischig (Glutamat)", x: ["Eine japanische Messerform mit einseitigem Schliff für Fisch", "Einen besonders scharfen Geschmack, ausgelöst durch Capsaicin", "Eine klebrige japanische Reissorte für Sushi und Onigiri"], e: "Neben süß, sauer, salzig und bitter – z. B. in Parmesan, Tomaten, Sojasauce." },
  { id: "k101", f: "Was ist Safran?", r: "Die getrockneten Blütennarben einer Krokusart", x: ["Gemahlene, getrocknete Kurkumawurzel aus Indien", "Getrocknete Blütenblätter der Ringelblume", "Ein Gewürz aus edelsüßem Paprika"], e: "Das teuerste Gewürz der Welt – jede Narbe wird von Hand gepflückt." },
  { id: "k102", f: "Vanille ist die Frucht einer …", r: "Orchidee", x: ["Palme", "Bohnenpflanze", "Lilie"], e: "Die Schoten werden fermentiert, bis sie dunkel und aromatisch sind." },
  { id: "k103", f: "Was sind Kapern?", r: "Die eingelegten Blütenknospen des Kapernstrauchs", x: ["Kleine, in Salzlake eingelegte grüne Oliven", "Unreife, grüne Pfefferkörner, in Essig und Salz eingelegt", "Die eingelegten Samen der Kapuzinerkresse"], e: "Kapernäpfel sind dagegen die Früchte." },
  { id: "k104", f: "Was ist weißer Pfeffer?", r: "Reife, geschälte Beeren derselben Pflanze wie schwarzer Pfeffer", x: ["Die Beeren einer eigenen Pfefferpflanze mit weißen Blüten", "Schwarzer Pfeffer, der nach der Ernte mit Chlor gebleicht wurde", "Getrocknete und gemahlene weiße Chilischoten"], e: "Grün = unreif, schwarz = unreif getrocknet, weiß = reif und geschält." },
  { id: "k105", f: "Ist rosa Pfeffer ein echter Pfeffer?", r: "Nein – es sind die Früchte des Pfefferbaums (Schinus)", x: ["Ja – es ist reifer schwarzer Pfeffer", "Ja – es ist gefärbter weißer Pfeffer aus Indien", "Nein – es sind getrocknete, rot gefärbte Johannisbeeren"], e: "Er schmeckt mild und leicht süßlich." },
  { id: "k106", f: "Was ist Macis (Muskatblüte)?", r: "Der rote Samenmantel um die Muskatnuss", x: ["Die getrocknete Blüte des Muskatbaums", "Fein gemahlene Muskatnuss aus Grenada", "Eine milde Zimtsorte aus Sri Lanka"], e: "Feiner im Geschmack als die Nuss selbst." },
  { id: "k107", f: "Wie heißt Cumin auf Deutsch?", r: "Kreuzkümmel", x: ["Kümmel", "Koriander", "Schwarzkümmel"], e: "Nicht verwechseln: Kümmel schmeckt ganz anders." },
  { id: "k108", f: "Was ist Topinambur?", r: "Die Knolle einer Sonnenblumenart", x: ["Eine alte, festkochende Kartoffelsorte", "Die Wurzel des Knollenselleries", "Eine milde Ingwerart"], e: "Leicht nussig, auch „Erdartischocke“ genannt." },
  { id: "k109", f: "Was ist Rhabarber botanisch?", r: "Ein Gemüse (Knöterichgewächs)", x: ["Ein Obst (Rosengewächs)", "Ein Getreide (Süßgras)", "Ein Obst (Stachelbeergewächs)"], e: "Gegessen werden die Stiele – die Blätter sind ungenießbar." },
  { id: "k110", f: "Welches Gemüse ist KEIN Nachtschattengewächs?", r: "Zucchini", x: ["Aubergine", "Paprika", "Kartoffel"], e: "Die Zucchini ist ein Kürbisgewächs." },
  { id: "k111", f: "Zu welcher Pflanzenfamilie gehört die Avocado?", r: "Lorbeergewächse", x: ["Palmengewächse", "Kürbisgewächse", "Rosengewächse"], e: "Verwandt mit Lorbeer und Zimt." },
  { id: "k112", f: "Wann endet traditionell die Spargelsaison in Deutschland?", r: "Am 24. Juni (Johannistag)", x: ["Am 1. Mai (Tag der Arbeit)", "Am 15. August (Mariä Himmelfahrt)", "Am 30. September"], e: "Danach darf sich die Pflanze für das nächste Jahr erholen." },
  { id: "k113", f: "Mit welchen giftigen Pflanzen kann Bärlauch verwechselt werden?", r: "Maiglöckchen und Herbstzeitlose", x: ["Löwenzahn und Große Brennnessel", "Spinat und Mangold", "Sauerampfer und Gartenkresse"], e: "Bärlauch riecht beim Zerreiben deutlich nach Knoblauch." },
  { id: "k114", f: "Was ist ein „Chinois“?", r: "Ein feines, spitzes Sieb", x: ["Ein Wok aus Karbonstahl", "Ein Paar Essstäbchen aus Holz", "Ein elektrischer Reiskocher"], e: "Spitzsieb – zum Passieren von Fonds und Saucen." },
  { id: "k115", f: "Was ist eine Sauteuse?", r: "Eine Schwenkpfanne mit schrägem Rand", x: ["Eine Saucenkelle mit Ausgießer", "Eine Fritteuse mit zwei Körben", "Ein Bräter mit schwerem Gusseisendeckel"], e: "Zum Sautieren und Reduzieren." },
  { id: "k116", f: "Welche Maße hat ein Gastronorm-Behälter GN 1/1?", r: "530 × 325 mm", x: ["600 × 400 mm", "500 × 300 mm", "650 × 530 mm"], e: "GN 2/1 ist 650 × 530 mm, GN 1/2 ist 325 × 265 mm." },
  { id: "k117", f: "Was kann ein Kombidämpfer?", r: "Heißluft und Dampf einzeln oder kombiniert", x: ["Nur Dampf, ohne Heißluft oder Grillfunktion", "Nur Mikrowelle und Umluft kombiniert", "Nur Grillen und Warmhalten bei 65 °C"], e: "Das Arbeitstier moderner Profiküchen." },
  { id: "k118", f: "Was macht ein Wetzstahl?", r: "Er richtet die Schneide wieder auf", x: ["Er schleift einen neuen Schliff ins Messer", "Er poliert die Klinge auf Hochglanz", "Er entfernt Rost von der Klinge"], e: "Für einen neuen Schliff braucht man einen Schleifstein." },
  { id: "k119", f: "Was bedeutet „nappieren“?", r: "Ein Gericht mit Sauce überziehen", x: ["Eine Stoffserviette kunstvoll falten", "Fleisch in ein Schweinenetz einwickeln", "Kurz in kochendes Wasser tauchen"], e: "Eine Sauce „nappiert“, wenn sie den Löffelrücken überzieht." },
  { id: "k120", f: "Was bedeutet „poelieren“?", r: "Zartes Fleisch mit Butter und Röstgemüse zugedeckt im Ofen garen", x: ["In der Pfanne bei starker Hitze kurz von beiden Seiten anbraten", "Im Wasserbad knapp unter dem Siedepunkt pochieren", "Im Rauch über Buchenholzspänen langsam garen"], e: "Zum Schluss ohne Deckel bräunen. Auf Deutsch: hellbraun dünsten." },
  { id: "k121", f: "Was bedeutet „arrosieren“?", r: "Fleisch beim Braten immer wieder mit heißem Fett übergießen", x: ["Fleisch zum Anrichten mit frischen Rosenblüten dekorieren", "Fleisch vor dem Braten mehrere Stunden in kaltem Wasser wässern", "Fleisch nach dem Braten in Alufolie ruhen lassen"], e: "Hält saftig und sorgt für gleichmäßige Bräunung." },
  { id: "k122", f: "Was ist „Gravad Lachs“?", r: "Lachs, der in Salz, Zucker und Dill gebeizt wurde", x: ["Heiß geräucherter Lachs über Buchenholz", "Gegrillter Lachs mit Dill und Zitronenbutter", "Pochierter Lachs in Aspik mit Gurkenscheiben"], e: "Skandinavischer Klassiker, mit Senf-Dill-Sauce." },
  { id: "k123", f: "Bei welcher Temperatur wird kalt geräuchert?", r: "Unter etwa 25 °C", x: ["Bei 60–80 °C", "Bei 80–100 °C", "Bei über 120 °C"], e: "So entstehen roher Schinken und Räucherlachs." },
  { id: "k124", f: "Was ist ein Jus?", r: "Ein kräftiger, eingekochter Bratensaft – ohne Mehl gebunden", x: ["Ein frisch gepresster Fruchtsaft, wie er zum Frühstück serviert wird", "Eine helle Sauce, mit Mehlschwitze und Sahne gebunden", "Ein feines Gemüsepüree, mit Butter aufgeschlagen"], e: "Entsteht aus Fond und Bratensatz durch Einkochen." },
  { id: "k125", f: "Was ist eine Glace de viande?", r: "Ein Fleischfond, eingekocht bis zur Sirupdicke", x: ["Gekochtes Fleisch in klarem Aspik", "Ein Speiseeis mit kandiertem Speck", "Ein im Ofen mit Honig glasierter Schweinebraten"], e: "Konzentrierter Geschmack zum Verfeinern von Saucen." },
  { id: "k126", f: "Was ist eine Chaud-froid-Sauce?", r: "Eine gelierende Sauce zum Überziehen kalter Gerichte", x: ["Eine heiße Schokoladensauce, die über kaltes Eis gegossen wird", "Eine warme Sauce, die zu kalten Austern serviert wird", "Ein lauwarmes Dressing aus Speck, Essig und Senf"], e: "Chaud = warm zubereitet, froid = kalt serviert – Reich des Garde-Manger." },
  { id: "k127", f: "Was ist eine Galantine?", r: "Entbeintes, gefülltes Geflügel – gerollt, pochiert und kalt serviert", x: ["Eine Torte aus Biskuit, Sahne und frischen Früchten – gekühlt serviert", "Ein bauchiges Rotweinglas für kräftige Burgunder-Weine", "Ein warmes Ragout aus Kalbfleisch – mit Reis serviert"], e: "Ein Klassiker der kalten Küche." },
  { id: "k128", f: "Was unterscheidet eine Pastete von einer Terrine?", r: "Pastete: im Teigmantel gebacken – Terrine: ohne Teig in der Form gegart", x: ["Pastete: immer aus Fisch – Terrine: immer aus Fleisch oder Wild", "Terrine: immer süß – Pastete: immer herzhaft und warm serviert", "Es gibt keinen Unterschied – beide Namen meinen dasselbe Gericht"], e: "Die Terrine heißt nach der Form, in der sie gart." },
  { id: "k129", f: "Was sind Rillettes?", r: "Im eigenen Fett gegartes, zerzupftes Fleisch als Brotaufstrich", x: ["Kleine, dünne Pfannkuchen aus Buchweizenmehl mit herzhafter Füllung", "Gedrehte Teigstangen aus Blätterteig mit Käse bestreut", "Gebratene Kartoffelspalten mit Rosmarin und grobem Meersalz"], e: "Klassisch aus Schwein oder Ente. Das Fleisch gart dabei langsam." },
  { id: "k130", f: "Was ist Coq au vin?", r: "Hahn bzw. Huhn in Rotwein geschmort", x: ["Ein Weißwein-Aperitif mit Cassis", "Gefülltes Huhn im Brotteig gebacken", "Hähnchen vom Grill mit Kräutern"], e: "Ein Klassiker aus Burgund – mit Speck, Pilzen und Perlzwiebeln." },
  { id: "k131", f: "Was ist eine Vichyssoise?", r: "Eine kalte Kartoffel-Lauch-Suppe", x: ["Ein französisches Mineralwasser", "Eine Fischsuppe aus Marseille mit Safran", "Ein Zitronendessert mit Baiser"], e: "Mit Sahne verfeinert, kalt serviert." },
  { id: "k132", f: "Was ist eine Bouillabaisse?", r: "Eine Fischsuppe aus Marseille", x: ["Eine kräftige Rindfleischbrühe", "Ein Gemüseauflauf aus der Provence", "Eine Spinattarte mit Ziegenkäse"], e: "Mit verschiedenen Fischen, Safran und Rouille." },
  { id: "k133", f: "Was gehört zum Beef Wellington?", r: "Rinderfilet mit Duxelles im Blätterteig", x: ["Rinderhack mit Kartoffelpüree überbacken", "Geschmorte Rinderbrust mit grünen Bohnen", "Roastbeef mit Yorkshire Pudding"], e: "Oft noch mit Schinken oder Crêpe umhüllt." },
  { id: "k134", f: "Was ist eine Sauce Cumberland?", r: "Kalte Sauce aus Johannisbeergelee, Portwein, Orange und Senf", x: ["Eine warme Käsesauce aus Cheddar, Ale und englischem Senf", "Eine Pfeffersauce mit Cognac, Sahne und grünem Pfeffer", "Eine Kräuter-Sahnesauce mit Minze, Essig und Zucker"], e: "Klassisch zu Wildpasteten und kaltem Braten." },
  { id: "k135", f: "Was ist eine Sauce Mornay?", r: "Eine Béchamel mit Käse (und Eigelb)", x: ["Eine Hollandaise mit Tomate (und Basilikum)", "Ein Rotweinjus mit Schalotten", "Eine Senfsauce mit Dill"], e: "Ideal zum Gratinieren." },
  { id: "k136", f: "Was ist eine Sauce Choron?", r: "Eine Béarnaise mit Tomate", x: ["Eine Béchamel mit Zwiebeln", "Eine Remoulade mit Gurke", "Ein brauner Kalbsjus"], e: "Gut zu gegrilltem Fleisch und Fisch." },
  { id: "k137", f: "Wer war die Namensgeberin von „Pfirsich Melba“?", r: "Die Opernsängerin Nellie Melba", x: ["Die Ehefrau von Auguste Escoffier", "Eine Kaiserin von Österreich", "Eine englische Köchin"], e: "Escoffier kreierte das Dessert mit Pfirsich, Vanilleeis und Himbeermark." },
  { id: "k138", f: "Was ist eine Tarte Tatin?", r: "Ein gestürzter, karamellisierter Apfelkuchen", x: ["Eine Zitronentarte mit abgeflämmtem Baiser", "Ein gebackener Käsekuchen nach Pariser Art", "Ein flüssiger Schokoladenkuchen aus der Form"], e: "Der Legende nach ein Missgeschick der Schwestern Tatin." },
  { id: "k139", f: "Was bedeutet „Panna cotta“?", r: "Gekochte Sahne", x: ["Kalte Milch", "Gebackene Creme", "Süßer Käse"], e: "Mit Gelatine gestockt und gestürzt serviert." },
  { id: "k140", f: "Warum brennt man eine neue Eisenpfanne ein?", r: "Damit sich eine schützende, antihaftende Patina bildet", x: ["Damit sie sich gleichmäßig dunkel verfärbt und edel aussieht", "Damit sie leichter wird und schneller heiß", "Damit der genietete Griff fest und dicht wird"], e: "Danach nur mit heißem Wasser reinigen, kein Spülmittel." },
  { id: "k141", f: "Was ist ein Fond?", r: "Ein kräftiger, ausgekochter Grundsud – Basis für Saucen und Suppen", x: ["Der Boden einer Pfanne, in dem sich beim Braten der Bratensatz sammelt", "Eine fertige, mit Mehlschwitze gebundene Sauce zum Anrichten", "Ein gebackener Dessertboden aus Biskuit oder Mürbeteig"], e: "Fond = Grund. Weiß (ungeröstet) oder braun (angeröstet)." },
  { id: "k142", f: "Was bedeutet „abschäumen“?", r: "Den Eiweißschaum von kochenden Brühen und Fonds abschöpfen", x: ["Milch für den Cappuccino mit der Dampflanze aufschäumen", "Eiweiß mit einer Prise Salz steif schlagen", "Das flüssige Fett vom Bratensatz abgießen"], e: "So bleibt der Fond klar." },
  { id: "k143", f: "Wie nennt man das Schmoren in der Fachsprache?", r: "Braisieren", x: ["Blanchieren", "Pochieren", "Frittieren"], e: "Anbraten, dann in wenig Flüssigkeit zugedeckt garen – für Rouladen, Gulasch, Haxen." },
  { id: "k144", f: "Was bedeutet „glasieren“ bei Gemüse?", r: "Mit Butter, Zucker und wenig Flüssigkeit garen, bis es glänzt", x: ["Mit verquirltem Eiweiß bestreichen und im heißen Ofen goldbraun backen", "Mit Zuckerguss überziehen und trocknen lassen", "Im Glas einkochen und mit Essigsud haltbar machen"], e: "Klassisch: glasierte Karotten." },
  { id: "k145", f: "Wofür ist der Pâtissier zuständig?", r: "Desserts, Gebäck und Backwaren", x: ["Pasteten, Terrinen und Galantinen", "Kartoffelgerichte und Beilagen", "Kalte Saucen und Dressings"], e: "In großen Häusern mit eigener Konditorei." },
  { id: "k146", f: "Was ist ein „Chef de Partie“?", r: "Ein Postenchef – leitet einen Bereich wie Saucen oder Fisch", x: ["Der Gastgeber einer Feier, der das Menü bestellt", "Der Chef des Service – leitet die Kellner im Restaurant", "Ein Lehrling, der alle Partien nacheinander durchläuft"], e: "Er hat oft Commis und Auszubildende unter sich." },
  { id: "k147", f: "Was ist eine Etamine (Passiertuch)?", r: "Ein Tuch zum Passieren von Fonds, Saucen und Gelees", x: ["Ein dicker Topflappen aus Leinen für heiße Griffe", "Eine hohe Kochmütze aus gestärktem Baumwollstoff", "Eine lange Vorbinder-Schürze aus Leinen"], e: "Besonders fein – für glasklare Ergebnisse." },
  { id: "k148", f: "Was bedeutet „legieren“?", r: "Eine Suppe oder Sauce mit Eigelb und Sahne binden", x: ["Verschiedene Metalle für Töpfe und Pfannen mischen", "Gemüse in feine Streifen von etwa 1 mm schneiden", "Mageres Fleisch mit dünnen Speckscheiben umwickeln"], e: "Mit der Liaison – nicht mehr aufkochen." },
  { id: "k149", f: "Was ist eine Farce?", r: "Eine fein zerkleinerte Füllmasse, z. B. aus Fleisch oder Fisch", x: ["Ein derbes Theaterstück, das sich über die Küche lustig macht", "Ein grobes Gewürzsalz mit Kräutern und Knoblauch", "Ein Fruchtmus aus gekochten Äpfeln, z. B. als Füllung"], e: "Mit Sahne aufgezogen heißt sie Mousseline-Farce." },
  { id: "k150", f: "Was bedeutet „flambieren“?", r: "Ein Gericht mit hochprozentigem Alkohol übergießen und anzünden", x: ["Zucker auf einer Creme mit dem Bunsenbrenner schmelzen und karamellisieren", "Fleisch über offenem Feuer auf dem Holzkohlegrill grillen", "Ein Gericht mit frischer Chili und Pfeffer scharf würzen"], e: "Klassisch: Crêpes Suzette – Vorsicht unter der Dunstabzugshaube!" },
  // ----- 🎖️ Meisterfragen (m: true) – schwerer, zählen doppelt (2.15.0) -----
  { id: "k151", m: true, f: "Was ist eine Sauce Espagnole?", r: "Braune Grundsauce aus braunem Fond, brauner Mehlschwitze und Röstgemüse", x: ["Eine spanische Paprika-Knoblauch-Sauce mit Olivenöl und Mandeln", "Eine kalte Sauce aus Olivenöl, Sherryessig und gehackten Eiern", "Eine Weißweinsauce mit Safran, Fischfond und Muscheln"], e: "Eine der fünf Grundsaucen nach Escoffier – zusammen mit braunem Fond eingekocht ergibt sie die Demi-glace. Dazu kommen Tomaten." },
  { id: "k152", m: true, f: "Was ist eine Sauce Allemande?", r: "Eine Kalbsvelouté, mit Eigelb legiert und mit Zitrone abgeschmeckt", x: ["Eine scharfe Senfsauce zu Weißwürsten, mit süßem Senf", "Eine braune Biersauce mit Kümmel, Zwiebeln und Malzzucker", "Eine Meerrettich-Sahne-Sauce, mit Apfel und Zitrone abgeschmeckt"], e: "Die „deutsche Sauce“ heißt auch Sauce Parisienne." },
  { id: "k153", m: true, f: "Was ist eine Sauce Suprême?", r: "Eine Geflügelvelouté, mit Sahne und Butter verfeinert", x: ["Eine Trüffel-Demi-glace, mit Madeira und Butter verfeinert", "Eine Hollandaise mit Orangensaft und Orangenschale", "Eine Tomatensauce mit Speck und Zwiebeln"], e: "Klassisch zu pochiertem Geflügel." },
  { id: "k154", m: true, f: "Was ist eine Sauce Maltaise?", r: "Eine Hollandaise mit Blutorange", x: ["Eine Béchamel mit Malzbier", "Eine Kapernsauce aus Malta", "Eine Tomatensauce mit schwarzen Oliven"], e: "Klassisch zu Spargel." },
  { id: "k155", m: true, f: "Was ist eine Sauce Mousseline?", r: "Eine Hollandaise mit geschlagener Sahne", x: ["Eine Sauce aus Kartoffelpüree und Brühe", "Eine Béarnaise mit Tomaten", "Eine Weißweinsauce mit Muscheln"], e: "Besonders luftig – auch Sauce Chantilly genannt." },
  { id: "k156", m: true, f: "Was ist eine Sauce Foyot?", r: "Eine Béarnaise mit Fleischglace", x: ["Eine Béchamel mit Gruyère", "Eine Rotweinsauce mit Rindermark", "Eine Krebsbutter-Sauce"], e: "Benannt nach dem Pariser Restaurant Foyot." },
  { id: "k157", m: true, f: "Was ist eine Sauce Aurore?", r: "Eine Velouté mit Tomatenpüree", x: ["Eine Hollandaise mit Safran", "Eine braune Sauce mit Rotwein", "Eine Vinaigrette mit gehacktem Ei"], e: "Aurore = Morgenröte – wegen der zartrosa Farbe." },
  { id: "k158", m: true, f: "Was ist eine Sauce Nantua?", r: "Eine Sauce mit Flusskrebsbutter und Krebsschwänzen", x: ["Eine Sauce mit Dijon-Senf, Estragon und Weißwein", "Eine Sauce mit pochierten Austern und Champagner", "Eine Sauce mit Waldpilzen, Sahne und Madeira"], e: "Klassisch zu Hechtklößchen (Quenelles de brochet)." },
  { id: "k159", m: true, f: "Was ist eine Sauce Périgueux?", r: "Eine Demi-glace mit Madeira und Trüffeln", x: ["Eine Walnusssauce mit Sahne und Walnussöl", "Eine Entenleber-Sahne-Sauce", "Eine Pfeffersauce mit Cognac und Sahne"], e: "Benannt nach Périgueux im Périgord, der Heimat der schwarzen Trüffel." },
  { id: "k160", m: true, f: "Was ist eine Sauce Bigarade?", r: "Eine Bitterorangen-Sauce zur Ente", x: ["Eine Kirschsauce zum Rehrücken", "Eine Apfelsauce zum Spanferkel", "Eine Preiselbeersauce zum Hirschrücken"], e: "Bigarade = Bitterorange (Pomeranze) – Canard à l’orange." },
  { id: "k161", m: true, f: "Was ist eine Sauce Robert?", r: "Eine braune Sauce mit Zwiebeln, Weißwein und Senf", x: ["Eine Hollandaise mit edelsüßem Paprika und Chili", "Eine kalte Kräutersauce mit Joghurt und Knoblauch", "Eine Krabbensauce mit Dill und Sahne"], e: "Eine der ältesten französischen Saucen – klassisch zu Schweinefleisch." },
  { id: "k162", m: true, f: "Wie heißt Escoffiers berühmtes Kochbuch?", r: "Le Guide Culinaire", x: ["Larousse Gastronomique", "Der Silberlöffel", "Le Répertoire de la Cuisine"], e: "Erschienen 1903 – bis heute ein Standardwerk." },
  { id: "k163", m: true, f: "Was bedeutet „à la Florentine“?", r: "Mit Spinat", x: ["Mit Tomaten", "Mit Pilzen", "Mit Artischocken"], e: "Z. B. Eier oder Fisch auf Blattspinat mit Mornay überbacken." },
  { id: "k164", m: true, f: "Was bedeutet „à la Dubarry“?", r: "Mit Blumenkohl", x: ["Mit Spargel", "Mit Schwarzwurzeln", "Mit Karotten"], e: "Benannt nach Madame du Barry – Crème Dubarry ist eine Blumenkohlcremesuppe." },
  { id: "k165", m: true, f: "Was bedeutet „à la Crécy“?", r: "Mit Karotten", x: ["Mit Kartoffeln", "Mit Lauch", "Mit Sellerie"], e: "Crécy war für seine Karotten bekannt – Potage Crécy ist Karottensuppe." },
  { id: "k166", m: true, f: "Was bedeutet „à la Parmentier“?", r: "Mit Kartoffeln", x: ["Mit Parmesan", "Mit Parmaschinken", "Mit Kräutern"], e: "Nach Antoine Parmentier, der die Kartoffel in Frankreich bekannt machte." },
  { id: "k167", m: true, f: "Was bedeutet „à la Clamart“?", r: "Mit Erbsen", x: ["Mit Muscheln", "Mit Bohnen", "Mit Linsen"], e: "Clamart bei Paris war berühmt für seine Erbsen." },
  { id: "k168", m: true, f: "Was bedeutet „Argenteuil“ in einem Gerichtsnamen?", r: "Mit Spargel", x: ["Mit Silberzwiebeln", "Mit Austern", "Mit Mandeln"], e: "Argenteuil bei Paris war für seinen Spargel bekannt." },
  { id: "k169", m: true, f: "Was ist „Royale“ als Suppeneinlage?", r: "Eierstich – im Wasserbad gestockte, gewürfelte Eiermilch", x: ["Klare Brühe, mit einem Schuss Champagner aufgegossen", "Kleine Fleischklößchen aus Kalbsbrät, in Brühe gegart", "Geröstete Weißbrotwürfel, in Butter goldbraun gebraten"], e: "Klassisch in der Consommé Royale. Er wird in Formen geschnitten." },
  { id: "k170", m: true, f: "Was sind Pommes Dauphine?", r: "Kartoffelmasse mit Brandteig vermischt, zu Bällchen geformt und frittiert", x: ["In Sahne und Milch gegarte, mit Käse im Ofen überbackene Kartoffelscheiben", "Dünne Kartoffelstäbchen aus rohen Kartoffeln, zweimal frittiert", "Gefüllte Ofenkartoffeln mit Sauerrahm und Schnittlauch"], e: "Nicht verwechseln mit dem Gratin dauphinois (Kartoffelgratin)." },
  { id: "k171", m: true, f: "Was sind Pommes Macaire?", r: "Küchlein aus dem Inneren gebackener Kartoffeln, mit Butter gebraten", x: ["Dünne Kartoffelspiralen, am Spieß aufgedreht und in heißem Öl frittiert", "Kartoffeln in Würfeln, in kräftiger Brühe mit Lauch und Speck gegart", "Kartoffelbrei mit frisch geriebenem Meerrettich und brauner Butter"], e: "Die Kartoffeln werden in der Schale gebacken, ausgehöhlt und zu Küchlein geformt." },
  { id: "k172", m: true, f: "Was sind Pommes Anna?", r: "Dünne Kartoffelscheiben, in Butter geschichtet und als Torte gebacken", x: ["Gefüllte Kartoffelkroketten mit flüssigem Käsekern, in Bröseln gewälzt", "Kartoffelpuffer aus rohen Kartoffeln, mit Apfelmus serviert", "Eine sämige Kartoffelsuppe mit Lauch, Speck und Majoran"], e: "Klassisch in einer speziellen Kupferform (Cocotte à pommes Anna)." },
  { id: "k173", m: true, f: "Was ist ein Salpicon?", r: "Feine Würfel von Fleisch, Fisch oder Pilzen, mit Sauce gebunden", x: ["Ein spanischer Eintopf aus weißen Bohnen, Chorizo und Paprika", "Ein grobes Würzsalz mit getrockneten Kräutern und Knoblauch", "Ein dünner Pfannkuchen aus Maismehl mit scharfer Füllung"], e: "Z. B. als Füllung für Pastetchen (Vol-au-vent) oder Kroketten. Verwendet als Füllung oder Einlage." },
  { id: "k174", m: true, f: "Was ist ein Fumet?", r: "Ein kräftiger, kurz gekochter Fischfond – oft mit Weißwein", x: ["Ein kleiner Räucherofen für Fisch und Fleisch", "Ein kräftiger Bratensatz vom Wild, mit Rotwein gelöst", "Eine teure Pilzessenz aus schwarzen Trüffeln und Madeira"], e: "Fumet de poisson – Basis für Fischsaucen." },
  { id: "k175", m: true, f: "Wie lange sollte ein Fischfond höchstens kochen?", r: "Etwa 20–30 Minuten", x: ["Etwa 2–3 Stunden", "Etwa 6–8 Stunden", "Einen ganzen Arbeitstag"], e: "Zu lange gekocht wird er trüb und bitter." },
  { id: "k176", m: true, f: "Was ist Matignon?", r: "Feines Röstgemüse mit Schinken oder Speck, in Butter gedünstet", x: ["Ein Rinderschmorbraten mit Rotwein, Speck und Perlzwiebeln", "Eine Mandelcreme mit Rum und Butter als Füllung für Tartes", "Eine Kräuterkruste aus Bröseln, Butter und Petersilie für Lamm"], e: "Wird mitgeschmort oder mitgegessen – im Gegensatz zum Mirepoix." },
  { id: "k177", m: true, f: "Was ist Tournedos Rossini?", r: "Rinderfiletsteak mit Gänsestopfleber, Trüffel und Madeirasauce", x: ["Rinderroulade mit Gurke, Speck, Senf und Zwiebeln in Rotweinsauce", "Dünn aufgeschnittenes Kalbsfilet mit Thunfisch-Kapern-Sauce", "Rinderfilet mit Pilzduxelles und Schinken im Blätterteig gebacken"], e: "Benannt nach dem Komponisten Gioachino Rossini, einem großen Feinschmecker." },
  { id: "k178", m: true, f: "Was ist Sole Colbert?", r: "Panierte, frittierte Seezunge ohne Mittelgräte, gefüllt mit Kräuterbutter", x: ["Seezunge im Ganzen in Champagner pochiert, mit Sahne- und Hummersauce überzogen", "Seezungenröllchen mit Lachsfarce, in Weißwein gegart und glasiert", "Gegrillte Seezunge mit Tomaten, Kapern und brauner Butter"], e: "Die Colbertbutter ist eine Kräuterbutter mit Fleischglace." },
  { id: "k179", m: true, f: "Wie rettet man eine geronnene Hollandaise?", r: "Ein frisches Eigelb aufschlagen und die geronnene Sauce langsam einrühren", x: ["Die Sauce kräftig aufkochen lassen, bis sich die Butter wieder verbindet", "Etwas Mehl einstreuen und die Sauce damit abbinden und glatt rühren", "Die Sauce mit kalter Butter vermischen und kurz im Tiefkühler anziehen lassen"], e: "Die Emulsion wird so Stück für Stück neu aufgebaut. Statt Eigelb geht auch ein Schuss kaltes Wasser." },
  { id: "k180", m: true, f: "Was ist Kalbsbries?", r: "Die Thymusdrüse des Kalbes", x: ["Die Schilddrüse des Kalbes", "Das Rückenmark des Kalbes", "Die Lymphknoten des Kalbes"], e: "Gilt als Delikatesse – vor der Zubereitung wässern, blanchieren und häuten." },
  { id: "k181", m: true, f: "Was ist Kronfleisch?", r: "Das Zwerchfell (Saumfleisch) vom Rind", x: ["Das Fleisch vom Kopf (Backe) des Rindes", "Der Rinderschwanz (Ochsenschwanz)", "Das Fleisch der Hochrippe (Rib-Eye)"], e: "Bayerische Spezialität – im französischen „Hampe“, in den USA „Skirt Steak“." },
  { id: "k182", m: true, f: "Was ist der Nierenzapfen (Onglet)?", r: "Ein Muskel am Zwerchfell zwischen Niere und Rippen vom Rind", x: ["Ein kleines Stück aus dem Filetkopf des Rinderfilets, sehr zart", "Ein Teil der Hüfte, direkt unter dem Tafelspitz", "Ein Stück aus der Brust, nahe dem Brustbein vom Rind"], e: "Kräftig im Geschmack – in Frankreich der Bistro-Klassiker „Onglet à l’échalote“." },
  { id: "k183", m: true, f: "Aus welchem Teil vom Rind stammt das Flat-Iron-Steak?", r: "Aus der Schulter (Schaufelstück)", x: ["Aus der Hüfte (Hüftdeckel)", "Aus der Flanke (Bauchlappen)", "Aus dem Roastbeef (flache Lende)"], e: "Die Mittelsehne wird herausgeschnitten – übrig bleiben zwei zarte, flache Steaks." },
  { id: "k184", m: true, f: "Was ist eine Panade für Farcen?", r: "Ein Bindemittel aus z. B. eingeweichtem Brot, Mehl oder Reis", x: ["Die knusprige Brotkruste, die beim Panieren entsteht", "Eine Gewürzmischung aus Salz, Pfeffer und Muskat für Farcen", "Eine klare Fischsuppe als Grundlage für Fischfarcen"], e: "Sie bindet die Farce und macht sie saftiger." },
  { id: "k185", m: true, f: "Was ist Beurre Maître d’hôtel?", r: "Kräuterbutter mit Petersilie und Zitronensaft", x: ["Gebräunte Butter mit Kapern und Zitronenfilets", "Butter mit gehackten Sardellen und Knoblauch", "Süße Butter mit Honig und Zimt"], e: "Klassisch in Scheiben auf Grillfleisch und Fisch." },
  { id: "k186", m: true, f: "Bei welcher Temperatur verarbeitet man temperierte dunkle Kuvertüre?", r: "Bei etwa 31–32 °C", x: ["Bei etwa 22–24 °C", "Bei etwa 40–45 °C", "Bei etwa 55–60 °C"], e: "Erst schmelzen (ca. 45–50 °C), dann abkühlen und wieder leicht erwärmen – so glänzt und knackt sie." },
  { id: "k187", m: true, f: "Was ist ein „Consommé double“?", r: "Eine doppelt kräftige Kraftbrühe", x: ["Zwei verschiedene Suppen in einer Tasse", "Eine Suppe mit zwei Einlagen", "Eine kalte und eine warme Brühe"], e: "Mit doppelter Menge Klärfleisch besonders konzentriert." },
  { id: "k188", m: true, f: "Was bedeutet „à la nage“?", r: "In einem aromatischen Sud gegart und darin serviert", x: ["Nach Art der Nonnen, mit Mandeln und Honig zubereitet", "Auf einem Bett aus frischen Bandnudeln angerichtet", "In Eiswasser schwimmend gekühlt und kalt serviert"], e: "Nage = Schwimmen – das Gargut „schwimmt“ im Sud. Meist Fisch oder Krustentiere." },
  { id: "k189", m: true, f: "Was ist ein Pot-au-feu?", r: "Ein Eintopf aus gekochtem Rindfleisch und Gemüse", x: ["Ein Käsefondue aus Gruyère und Weißwein im Caquelon", "Eine heiße Feuerzangenbowle mit Rum und Rotwein", "Ein Grillspieß mit Lammfleisch über offenem Feuer"], e: "Brühe und Fleisch werden oft getrennt serviert. Ein Klassiker der französischen Küche." },
  { id: "k190", m: true, f: "Was ist ein Vol-au-vent?", r: "Eine Blätterteigpastete, meist mit Ragout gefüllt", x: ["Ein Windbeutel aus Brandteig mit Sahne gefüllt", "Ein luftiges Soufflé mit Käse aus dem Ofen", "Ein Fischgericht, im Wind getrocknet und gegrillt"], e: "Vol-au-vent = „Flug im Wind“ – wegen des luftigen Teigs." },
  // 2.25.0 (Wunsch Hansi „noch 100 dazu, jedes Mal anders anfangen“): 80 normale + 20 Meisterfragen, bewusst mit wechselnden Frageanfängen
  { id: "k191", f: "Woran erkennt man frischen Fisch am Auge?", r: "Das Auge ist klar, prall und glänzend", x: ["Das Auge ist milchig trüb und leicht eingefallen", "Das Auge ist rötlich verfärbt und sehr weich", "Das Auge fehlt, weil es beim Fang entfernt wird"], e: "Klare, gewölbte Augen, rote Kiemen und festes Fleisch. Trübe, eingesunkene Augen deuten auf alten Fisch." },
  { id: "k192", f: "Welches Gemüse gehört NICHT in eine klassische Ratatouille?", r: "Kartoffeln", x: ["Auberginen", "Zucchini", "Paprika"], e: "Ratatouille aus der Provence: Aubergine, Zucchini, Paprika, Tomate, Zwiebel, Knoblauch und Kräuter – ohne Kartoffeln." },
  { id: "k193", f: "Wie nennt man in Italien Nudeln, die noch einen leichten Biss haben?", r: "al dente", x: ["al forno", "al cartoccio", "alla brace"], e: "„Al dente“ heißt „für den Zahn“ – die Nudel hat innen noch einen leichten Kern." },
  { id: "k194", f: "Woher stammt der Parmigiano Reggiano?", r: "Aus der Emilia-Romagna und einem Teil der Lombardei", x: ["Aus der Toskana rund um Florenz und Siena", "Aus Sardinien und dem Süden der Insel Korsika", "Aus dem Piemont rund um die Städte Turin und Asti"], e: "Geschützte Ursprungsbezeichnung: Parma, Reggio Emilia, Modena, Teile von Bologna und Mantua." },
  { id: "k195", f: "Ab welcher Kerntemperatur gilt Geflügel als sicher durchgegart?", r: "Ab etwa 72 °C, mindestens 2 Minuten lang", x: ["Ab etwa 50 °C, mindestens 1 Minute lang", "Ab etwa 58 °C, mindestens 30 Sekunden lang", "Ab etwa 62 °C, sofort nach dem Erreichen"], e: "Bei 72 °C über 2 Minuten werden Salmonellen und Campylobacter sicher abgetötet." },
  { id: "k196", f: "Woraus wird klassischer Couscous hergestellt?", r: "Aus Hartweizengrieß", x: ["Aus gemahlenem Reis", "Aus feinem Maismehl", "Aus Kichererbsenmehl"], e: "Hartweizengrieß wird angefeuchtet, zu kleinen Kügelchen gerollt und gedämpft – traditionell im Couscoussier." },
  { id: "k197", f: "Wie heißt die Hähnchenbrust, an der noch der erste Flügelknochen sitzt?", r: "Suprême", x: ["Ballotine", "Paillard", "Crapaudine"], e: "Das Suprême de volaille wirkt elegant und bleibt saftiger. Paillard = dünn geklopfte Scheibe, Crapaudine = flach aufgeschnittenes Geflügel." },
  { id: "k198", f: "Warum sollte man Pilze nicht lange im Wasser waschen?", r: "Sie saugen Wasser auf und braten dann nicht", x: ["Sie verlieren dabei ihr gesamtes Eiweiß", "Sie werden durch das Wasser leicht giftig", "Sie färben sich sofort schwarz und bitter"], e: "Pilze besser trocken putzen oder nur kurz abbrausen – nasse Pilze schmoren statt zu bräunen." },
  { id: "k199", f: "Wofür nimmt man in der Küche einen Gemüsehobel (Mandoline)?", r: "Für gleichmäßig dünne Scheiben und Stifte", x: ["Zum Aufschlagen von Sahne und Eischnee", "Zum Entkernen von Kirschen und Oliven", "Zum Abseihen von Fonds und Saucen"], e: "Mit verstellbarer Klinge sehr exakt – aber immer den Fingerschutz benutzen!" },
  { id: "k200", f: "Welcher Käse gehört original auf eine Pizza Margherita?", r: "Mozzarella", x: ["Gorgonzola", "Pecorino", "Emmentaler"], e: "Tomate, Mozzarella, Basilikum – die Farben der italienischen Flagge, 1889 zu Ehren von Königin Margherita." },
  { id: "k201", f: "Nach wem ist die Béchamelsauce benannt?", r: "Nach Louis de Béchameil, Haushofmeister Ludwigs XIV.", x: ["Nach einem Dorf in der Normandie mit großer Milchwirtschaft", "Nach dem arabischen Wort für „weiße Sauce“", "Nach einem Mailänder Koch aus der Zeit der Renaissance"], e: "Ob er sie erfunden hat, ist umstritten – benannt wurde sie jedenfalls nach ihm." },
  { id: "k202", f: "Wie viel wiegt ein Ei der Gewichtsklasse M?", r: "53 bis unter 63 g", x: ["43 bis unter 53 g", "63 bis unter 73 g", "73 g und mehr"], e: "S unter 53 g, M 53 bis unter 63 g, L 63 bis unter 73 g, XL ab 73 g." },
  { id: "k203", f: "Auf einem Ei steht „0-DE-…“. Wofür steht die 0?", r: "Ökologische Erzeugung (Bio)", x: ["Freilandhaltung", "Bodenhaltung", "Käfig- bzw. Kleingruppenhaltung"], e: "0 = Bio, 1 = Freiland, 2 = Boden, 3 = Kleingruppe/Käfig. Danach folgt das Herkunftsland, z. B. DE." },
  { id: "k204", f: "Wobei hilft ein Schuss Essig im Wasser für pochierte Eier?", r: "Das Eiweiß stockt schneller und zerfasert weniger", x: ["Die Schale lässt sich anschließend leichter lösen", "Das Eigelb bekommt eine kräftigere gelbe Farbe", "Das Wasser kocht bei niedrigerer Temperatur"], e: "Säure beschleunigt das Gerinnen. Das Wasser soll dabei nur sieden, nicht sprudeln." },
  { id: "k205", f: "Welches Mehl verbirgt sich hinter der Type 405?", r: "Helles Weizenmehl, vor allem für Kuchen", x: ["Dunkles Roggenmehl für kräftiges Brot", "Vollkorn-Dinkelmehl mit dem ganzen Korn", "Mehl aus Buchweizen für Galettes"], e: "Die Type gibt den Mineralstoffgehalt an (mg je 100 g Trockenmasse) – je niedriger, desto heller und feiner." },
  { id: "k206", f: "Wie heißt das spanische Reisgericht aus der großen, flachen Pfanne?", r: "Paella", x: ["Risotto", "Pilaw", "Jambalaya"], e: "Ursprünglich aus Valencia – eigentlich heißt die Pfanne Paella. Typisch: Rundkornreis, Safran und die Kruste am Boden (Socarrat)." },
  { id: "k207", f: "Welcher Teil der Artischocke wird als „Artischockenboden“ gegessen?", r: "Der fleischige Blütenboden ohne Heu", x: ["Die äußeren, harten Hüllblätter", "Der lange, holzige Stiel", "Die violetten Blütenfäden im Inneren"], e: "Das „Heu“ (die unreifen Blüten) wird entfernt; Zitrone schützt den Boden vor dem Braunwerden." },
  { id: "k208", f: "Womit hält man geschnittene Äpfel am einfachsten hell?", r: "Mit ein paar Tropfen Zitronensaft", x: ["Mit einer Prise Natron darüber", "Kurz in warmes Zuckerwasser legen", "Mit Öl einpinseln und offen lagern"], e: "Säure und Vitamin C bremsen die Enzyme, die das Obst braun färben." },
  { id: "k209", f: "Welcher dieser Fische lebt im Süßwasser?", r: "Zander", x: ["Kabeljau", "Seelachs", "Steinbutt"], e: "Zander lebt in Seen und Flüssen. Kabeljau, Seelachs (Köhler) und Steinbutt sind Meeresfische." },
  { id: "k210", f: "Wie nennt man den Kabeljau aus der Ostsee?", r: "Dorsch", x: ["Schellfisch", "Wittling", "Leng"], e: "Dorsch heißt der Kabeljau aus der Ostsee – und der junge, noch nicht laichreife Kabeljau." },
  { id: "k211", f: "Wie wird „Dry Aged“ Beef gereift?", r: "Offen und trocken, oft am Knochen", x: ["Im Vakuumbeutel im eigenen Saft", "In Salzlake mit Kräutern und Gewürzen", "Unter Rauch bei etwa 25 °C"], e: "Dry Aging: bei ca. 1–3 °C und kontrollierter Luftfeuchte über Wochen – das Aroma wird intensiver. Im Vakuum heißt es Wet Aging." },
  { id: "k212", f: "Warum lässt man ein Steak nach dem Braten kurz ruhen?", r: "Damit sich der Fleischsaft wieder verteilt", x: ["Damit es beim Servieren wieder kalt ist", "Damit das Salz vollständig verdunstet", "Damit die Kruste wieder weich wird"], e: "Ein paar Minuten Ruhe (je nach Größe) – sonst läuft beim Anschneiden mehr Saft aus." },
  { id: "k213", f: "Welches Gericht ist ein Klassiker der Schweizer Küche?", r: "Zürcher Geschnetzeltes", x: ["Thüringer Rostbratwurst", "Königsberger Klopse", "Leipziger Allerlei"], e: "Kalbfleischstreifen in Rahmsauce mit Champignons, dazu Rösti." },
  { id: "k214", f: "Aus welcher Küche stammt das Labskaus?", r: "Aus der Seefahrerküche Norddeutschlands", x: ["Aus der bayerischen Wirtshausküche", "Aus der Pfälzer Weinstubenküche", "Aus der schwäbischen Bauernküche"], e: "Gepökeltes Rindfleisch, Kartoffeln und Rote Bete, dazu Spiegelei, Rollmops und Gewürzgurke." },
  { id: "k215", f: "Bei welcher Temperatur arbeitet Backhefe am besten?", r: "Um 30 bis 35 °C", x: ["Um 5 bis 10 °C", "Um 50 bis 55 °C", "Um 70 bis 75 °C"], e: "Hefe mag es lauwarm. Ab etwa 45 °C leidet sie, ab etwa 55–60 °C stirbt sie ab." },
  { id: "k216", f: "Welche Zutat gibt Hummus neben Kichererbsen den typischen Geschmack?", r: "Tahin (Sesampaste)", x: ["Erdnussbutter", "Kokosmilch", "Griechischer Joghurt"], e: "Hummus: Kichererbsen, Tahin, Zitrone, Knoblauch und Olivenöl." },
  { id: "k217", f: "Woraus wird Tofu hergestellt?", r: "Aus geronnener Sojamilch", x: ["Aus gepressten Kichererbsen", "Aus Weizeneiweiß (Gluten)", "Aus fermentiertem Reis"], e: "Sojamilch wird mit einem Gerinnungsmittel (z. B. Nigari) dickgelegt und gepresst. Aus Weizeneiweiß macht man Seitan." },
  { id: "k218", f: "Wie heißt die japanische Brühe aus Kombu-Alge und Bonito-Flocken?", r: "Dashi", x: ["Ponzu", "Mirin", "Teriyaki"], e: "Dashi ist die Grundbrühe der japanischen Küche – Basis für Misosuppe und viele Saucen." },
  { id: "k219", f: "Welche Würzpaste ist Grundlage der Misosuppe?", r: "Fermentierte Sojabohnenpaste", x: ["Gemahlene Erdnüsse mit Chili", "Eingekochte Fischsauce mit Zucker", "Pürierter Ingwer mit Knoblauch"], e: "Miso: fermentierte Sojabohnen, oft mit Reis oder Gerste. Nicht mehr kochen lassen – sonst leidet das Aroma." },
  { id: "k220", f: "Aus welchem Land stammt Kimchi?", r: "Korea", x: ["Japan", "Thailand", "Vietnam"], e: "Milchsauer vergorener Chinakohl mit Chili, Knoblauch und Ingwer – ein Nationalgericht Koreas." },
  { id: "k221", f: "Welches Gewürz färbt Currypulver gelb?", r: "Kurkuma", x: ["Kreuzkümmel", "Koriandersamen", "Bockshornklee"], e: "Kurkuma (Gelbwurz) enthält den gelben Farbstoff Curcumin." },
  { id: "k222", f: "Woher hat „Pimentón de la Vera“ sein rauchiges Aroma?", r: "Vom Trocknen über Eichenholzrauch", x: ["Vom Rösten in heißem Olivenöl", "Vom Lagern in alten Sherryfässern", "Vom Einlegen in eine Salzlake"], e: "Die Paprika aus der spanischen Vera werden über Eichenholzfeuer getrocknet und dann gemahlen." },
  { id: "k223", f: "Welche Zitrusfrucht gibt dem Earl Grey sein Aroma?", r: "Bergamotte", x: ["Yuzu", "Blutorange", "Kumquat"], e: "Schwarztee mit Bergamotteöl – auch in der Pâtisserie beliebt." },
  { id: "k224", f: "Welches Messer hat eine schmale, biegsame Klinge?", r: "Das Filetiermesser", x: ["Das Hackbeil", "Das Wellenschliffmesser", "Das Kochmesser"], e: "Die flexible Klinge folgt den Gräten – ideal zum Filetieren von Fisch." },
  { id: "k225", f: "Welche Brettfarbe steht im verbreiteten Farbsystem für rohen Fisch?", r: "Blau", x: ["Grün", "Gelb", "Weiß"], e: "Üblich: Rot = rohes Fleisch, Blau = roher Fisch, Gelb = Geflügel, Grün = Obst/Gemüse, Weiß = Brot/Milchprodukte. Verbindlich ist das System im eigenen Betrieb." },
  { id: "k226", f: "Warum soll man gegarte Speisen zügig herunterkühlen?", r: "Um die keimkritische Zone schnell zu verlassen", x: ["Damit sie sich danach besser nachwürzen lassen", "Weil warme Speisen im Kühlraum verboten sind", "Damit sich die Vitamine beim Aufwärmen erholen"], e: "Zwischen etwa 10 und 60 °C vermehren sich Keime besonders gut – darum schnell, z. B. im Schnellkühler, abkühlen." },
  { id: "k227", f: "Wie nennt man die Temperatur, ab der ein Fett sichtbar raucht?", r: "Rauchpunkt", x: ["Schmelzpunkt", "Siedepunkt", "Flammpunkt"], e: "Über dem Rauchpunkt zersetzt sich das Fett und es entstehen schädliche Stoffe. Raffinierte Öle vertragen mehr Hitze." },
  { id: "k228", f: "Wie heißt geklärte Butter in der indischen Küche?", r: "Ghee", x: ["Paneer", "Raita", "Lassi"], e: "Ghee köchelt etwas länger als Butterschmalz – dadurch leicht nussig und hoch erhitzbar." },
  { id: "k229", f: "Welche Zutaten gehören in ein Pesto alla Genovese?", r: "Basilikum, Pinienkerne, Hartkäse, Knoblauch, Öl", x: ["Rucola, Walnüsse, Ziegenkäse, Zitrone und Öl", "Petersilie, Mandeln, Feta, Kapern und Essig", "Koriander, Erdnüsse, Chili, Limette und Öl"], e: "Aus Genua: Basilikum, Pinienkerne, Parmigiano und Pecorino, Knoblauch und Olivenöl – traditionell im Mörser." },
  { id: "k230", f: "Wie wird eine Rösti zubereitet?", r: "Geriebene Kartoffeln, flach in der Pfanne knusprig gebraten", x: ["Gekochte Kartoffeln, zerstampft und mit Milch verrührt", "Kartoffelscheiben, mit Sahne und Käse im Ofen gegart", "Kartoffelteig, zu Klößen geformt und in Wasser gegart"], e: "Schweizer Klassiker – aus rohen oder gekochten, grob geriebenen Kartoffeln." },
  { id: "k231", f: "Unter „Pommes Château“ versteht man …", r: "Tournierte, in Butter gebratene Kartoffeln", x: ["Kartoffelpüree mit Eigelb, aufgespritzt", "Hauchdünne, frittierte Kartoffelscheiben", "Kartoffelwürfel mit Speck und Zwiebeln"], e: "Tournierte Kartoffeln, blanchiert und in Butter goldbraun gebraten – klassisch zum Chateaubriand." },
  { id: "k232", f: "Wie heißen kleine, dünne Kalbsschnitzel auf Italienisch?", r: "Scaloppine", x: ["Involtini", "Arancini", "Bocconcini"], e: "Scaloppine werden oft mehliert und mit Zitrone, Marsala oder Weißwein abgelöscht." },
  { id: "k233", f: "Woraus bestehen sizilianische Arancini?", r: "Aus gefüllten, frittierten Reisbällchen", x: ["Aus kleinen Kartoffelklößen in Salbeibutter", "Aus Grießnocken in einer Tomatensauce", "Aus Nudelteigtaschen mit Ricottafüllung"], e: "Oft gefüllt mit Ragù, Erbsen und Mozzarella, paniert und goldbraun frittiert." },
  { id: "k234", f: "Welche Bezeichnung darf nur Schaumwein aus der französischen Champagne tragen?", r: "Champagner", x: ["Crémant", "Cava", "Franciacorta"], e: "Crémant ist Schaumwein aus anderen französischen Regionen, Cava kommt aus Spanien, Franciacorta aus der Lombardei." },
  { id: "k235", f: "Mit welcher Temperatur serviert man kräftigen Rotwein meist?", r: "Etwa 16 bis 18 °C", x: ["Etwa 6 bis 8 °C", "Etwa 22 bis 24 °C", "Etwa 26 bis 28 °C"], e: "„Zimmertemperatur“ meint die früher kühleren Räume. Leichte Rote eher um 14 °C." },
  { id: "k236", f: "Wer ist im Restaurant für Weinkarte und Weinberatung zuständig?", r: "Der Sommelier", x: ["Der Chef de Rang", "Der Commis de Rang", "Der Chef de Partie"], e: "Der Sommelier verantwortet Weinkarte, Weinkeller und die Beratung der Gäste." },
  { id: "k237", f: "Ab welcher Temperatur beginnt Haushaltszucker zu karamellisieren?", r: "Bei etwa 160 °C", x: ["Bei etwa 60 °C", "Bei etwa 100 °C", "Bei etwa 250 °C"], e: "Zucker schmilzt bei etwa 160–185 °C und karamellisiert dann rasch – kurz danach wird er bitter." },
  { id: "k238", f: "Wodurch geht ein klassischer Biskuit auf?", r: "Durch Luft im aufgeschlagenen Ei-Zucker-Schaum", x: ["Durch reichlich Backpulver im Mehl", "Durch Hefe und eine lange, warme Gare", "Durch zugesetztes Natron und Buttermilch"], e: "Klassischer Biskuit kommt ohne Triebmittel aus – die eingeschlagene Luft trägt ihn." },
  { id: "k239", f: "Warum schlägt man Eischnee in einer fettfreien Schüssel?", r: "Fett verhindert, dass der Schnee steif wird", x: ["Fett lässt den Eischnee gelb werden", "Fett macht den Schnee viel zu schnell fest", "Fett lässt das Eiweiß sofort gerinnen"], e: "Schon Spuren von Fett oder Eigelb stören den Aufbau des Schaums." },
  { id: "k240", f: "Wofür steht beim Brotbacken die Abkürzung „TA“?", r: "Teigausbeute", x: ["Teigausdehnung", "Trockenanteil", "Teigaufschlag"], e: "TA = Mehl + Flüssigkeit, bezogen auf 100 Teile Mehl: TA 165 heißt 100 g Mehl und 65 g Wasser." },
  { id: "k241", f: "Was passiert bei der „Stückgare“?", r: "Der geformte Teigling geht vor dem Backen auf", x: ["Der Teig kühlt nach dem Backen langsam aus", "Das Mehl quillt vor dem Kneten im Wasser", "Die Kruste wird nach dem Backen glasiert"], e: "Stockgare: der ganze Teig ruht nach dem Kneten. Stückgare: der fertig geformte Teigling geht noch einmal." },
  { id: "k242", f: "Was macht Mürbeteig zäh statt mürbe?", r: "Zu langes Kneten", x: ["Zu kalte Butter", "Zu kurzes Kneten", "Zu wenig Zucker"], e: "Langes Kneten bildet Gluten – darum kühl und zügig arbeiten." },
  { id: "k243", f: "Beim „Blindbacken“ wird …", r: "der Boden ohne Füllung vorgebacken", x: ["der Kuchen im ausgeschalteten Ofen gegart", "ohne Rezept nur nach Gefühl gebacken", "der Teig im Dunkeln gehen gelassen"], e: "Mit Backpapier und getrockneten Hülsenfrüchten beschwert – so bleibt der Boden flach und knusprig." },
  { id: "k244", f: "Welches italienische Dessert besteht aus Löffelbiskuit, Espresso und Mascarpone?", r: "Tiramisu", x: ["Zabaione", "Cassata", "Semifreddo"], e: "Tiramisù heißt „zieh mich hoch“ – wohl wegen Espresso und Kakao." },
  { id: "k245", f: "Aus welchem Land stammt der Kaiserschmarrn?", r: "Österreich", x: ["Schweiz", "Ungarn", "Tschechien"], e: "Klassiker der Wiener Mehlspeisküche – zerrissener, karamellisierter Pfannkuchen, oft mit Rosinen." },
  { id: "k246", f: "Was steckt in einer klassischen Linzer Torte?", r: "Nussteig mit Johannisbeerkonfitüre", x: ["Schokobiskuit mit Kirschen und Sahne", "Blätterteig mit Vanillecreme", "Hefeteig mit Mohn- und Quarkfüllung"], e: "Mürber Teig mit Haselnüssen oder Mandeln, Johannisbeer- oder Himbeerkonfitüre und Teiggitter obenauf." },
  { id: "k247", f: "Wodurch unterscheidet sich Kuvertüre von Tafelschokolade?", r: "Sie hat mehr Kakaobutter und fließt dünner", x: ["Sie enthält überhaupt keinen Zucker", "Sie ist immer weiße Schokolade ohne Kakaomasse", "Sie wird ganz ohne Kakao hergestellt"], e: "Kuvertüre hat mindestens 31 % Kakaobutter – ideal zum Überziehen und Temperieren." },
  { id: "k248", f: "Wofür braucht man Pektin?", r: "Zum Gelieren von Konfitüre und Gelee", x: ["Zum Aufschäumen von Milch für Cappuccino", "Zum Klären von trüben Fonds und Brühen", "Zum Mürbemachen von zähem Rindfleisch"], e: "Pektin steckt z. B. in Äpfeln und Zitrusschalen und braucht Zucker und Säure zum Gelieren." },
  { id: "k249", f: "Welcher Trüffel gilt als der teuerste?", r: "Der weiße Alba-Trüffel", x: ["Der Burgunder-Trüffel", "Der Sommertrüffel", "Der schwarze Périgord-Trüffel"], e: "Tuber magnatum aus dem Piemont – wird roh über Pasta, Risotto oder Ei gehobelt." },
  { id: "k250", f: "Wann haben Miesmuscheln traditionell Saison?", r: "In den Monaten mit „r“", x: ["Nur im Hochsommer", "Von Ostern bis Pfingsten", "Nur im Dezember"], e: "Faustregel September bis April. Dank Zucht heute fast ganzjährig, im Sommer aber oft magerer." },
  { id: "k251", f: "Welche rohen Miesmuscheln sortiert man aus?", r: "Offene, die sich beim Antippen nicht schließen", x: ["Fest geschlossene, die sich schwer anfühlen", "Solche mit kleinen Seepocken auf der Schale", "Solche, die frisch und angenehm nach Meer riechen"], e: "Offene Muscheln, die nicht reagieren, sind tot. Auch Muscheln mit beschädigter Schale wegwerfen." },
  { id: "k252", f: "Auf einer Garnelenpackung steht „16/20“. Was heißt das?", r: "16 bis 20 Stück je Pfund", x: ["16 bis 20 Gramm pro Garnele", "16 bis 20 Zentimeter Länge", "16 bis 20 Garnelen pro Portion"], e: "Die Zahl ist die Stückzahl je Gewichtseinheit – meist je englischem Pfund (454 g). Kleinere Zahl = größere Garnelen." },
  { id: "k253", f: "Welcher „Kaviar“ stammt vom Lachs?", r: "Keta-Kaviar", x: ["Beluga-Kaviar", "Bottarga", "Tobiko"], e: "Keta-Kaviar kommt vom Ketalachs; echter Kaviar nur vom Stör. Bottarga ist getrockneter Rogen, Tobiko Rogen vom Fliegenden Fisch." },
  { id: "k254", f: "Was kennzeichnet das Dämpfen?", r: "Garen im heißen Dampf, ohne das Wasser zu berühren", x: ["Garen in viel sprudelnd siedendem Salzwasser", "Garen in reichlich heißem Fett bei etwa 170 °C", "Garen unter starker Oberhitze im Salamander"], e: "Schonend: Nährstoffe und Farbe bleiben weitgehend erhalten, z. B. im Dämpfeinsatz oder Kombidämpfer." },
  { id: "k255", f: "Wie nennt man es, Zwiebeln in wenig Fett glasig zu garen, ohne dass sie Farbe nehmen?", r: "Anschwitzen", x: ["Abflämmen", "Anrösten", "Karamellisieren"], e: "Beim Anschwitzen werden die Zwiebeln glasig, aber nicht braun." },
  { id: "k256", f: "Welches Besteck liegt beim Eindecken rechts vom Teller?", r: "Messer und Suppenlöffel", x: ["Fleisch- und Fischgabel", "Dessertgabel und Kuchengabel", "Buttermesser und Brotgabel"], e: "Rechts Messer (Schneide zum Teller) und Suppenlöffel, links die Gabeln, Dessertbesteck oberhalb des Tellers." },
  { id: "k257", f: "Von welcher Seite setzt der Service den Teller beim Gast ein?", r: "Von rechts", x: ["Von links", "Von vorne über den Tisch", "Von hinten über die Schulter"], e: "Teller werden von rechts eingesetzt und ausgehoben; beim Vorlegen von der Platte geht man von links." },
  { id: "k258", f: "In welchem Bundesland sind Spätzle ein Nationalgericht?", r: "Baden-Württemberg", x: ["Schleswig-Holstein", "Sachsen", "Brandenburg"], e: "Schwäbische Spätzle werden vom Brett geschabt oder gepresst – Käsespätzle sind ein Klassiker." },
  { id: "k259", f: "Aus welcher Region stammt der Pumpernickel?", r: "Westfalen", x: ["Ostfriesland", "Oberbayern", "Thüringen"], e: "Roggenschrotbrot, mindestens 16 Stunden bei niedriger Temperatur gebacken – daher dunkel und leicht süßlich." },
  { id: "k260", f: "Wie heißt das Gericht aus Kartoffeln, Äpfeln und gebratener Blutwurst?", r: "Himmel un Ääd", x: ["Pannhas", "Töttchen", "Grünkohl mit Pinkel"], e: "„Himmel und Erde“: Äpfel vom Baum (Himmel) und Kartoffeln aus der Erde, dazu Blutwurst und Zwiebeln." },
  { id: "k261", f: "Woraus wird Rote Grütze gemacht?", r: "Aus roten Beeren und Saft, mit Stärke gebunden", x: ["Aus Roter Bete, Zucker und Essig gekocht", "Aus Hagebutten und Rotwein eingekocht", "Aus rotem Reis mit Milch und Zimt"], e: "Norddeutscher Klassiker, früher mit Grütze gebunden – dazu Vanillesauce oder Sahne." },
  { id: "k262", f: "Wann schmeckt Grünkohl traditionell am besten?", r: "Nach dem ersten Frost", x: ["Im Hochsommer bei voller Sonne", "Direkt nach der Blüte im Frühjahr", "Im September vor dem ersten Regen"], e: "Kälte lässt den Kohl mehr Zucker bilden – er wird milder." },
  { id: "k263", f: "Wie heißt der Steinpilz auf Italienisch?", r: "Porcino", x: ["Finferlo", "Chiodino", "Prataiolo"], e: "Funghi porcini – getrocknet ein kräftiges Würzmittel für Saucen und Risotto." },
  { id: "k264", f: "Welcher Speisepilz heißt in Österreich „Eierschwammerl“?", r: "Pfifferling", x: ["Champignon", "Austernpilz", "Morchel"], e: "Pfifferlinge trocken putzen und kurz scharf anbraten." },
  { id: "k265", f: "Welches Gemüse heißt in Österreich „Paradeiser“?", r: "Tomate", x: ["Paprika", "Aubergine", "Kürbis"], e: "Paradeiser = Tomate, Erdäpfel = Kartoffeln, Karfiol = Blumenkohl." },
  { id: "k266", f: "Was bekommt man in Wien, wenn man „Fisolen“ bestellt?", r: "Grüne Bohnen", x: ["Erbsen", "Linsen", "Dicke Bohnen"], e: "Fisolen sind grüne Bohnen – z. B. als Fisolengemüse mit Dille." },
  { id: "k267", f: "Wofür steht „g. g. A.“ auf Lebensmitteln?", r: "Geschützte geografische Angabe", x: ["Garantiert gentechnikfreier Anbau", "Geprüfte gastronomische Auswahl", "Gesetzlich geregelte Abfüllung"], e: "EU-Siegel: mindestens eine Produktionsstufe findet in der Region statt. Bei g. U. sind es alle Stufen." },
  { id: "k268", f: "Wann braucht ein Lebensmittel ein „zu verbrauchen bis“-Datum?", r: "Bei leicht verderblichen Waren wie Hackfleisch", x: ["Bei allen Konserven und abgepackten Trockenwaren", "Bei Lebensmitteln mit über 10 % Zucker", "Bei allen Produkten aus dem Ausland"], e: "Nach Ablauf des Verbrauchsdatums darf die Ware nicht mehr verkauft werden – anders als beim Mindesthaltbarkeitsdatum." },
  { id: "k269", f: "Das Mindesthaltbarkeitsdatum ist abgelaufen. Was gilt?", r: "Die Ware ist oft noch gut – vorher prüfen", x: ["Sie muss sofort entsorgt werden", "Sie darf nur noch gekocht gegessen werden", "Sie ist automatisch gesundheitsschädlich"], e: "Das MHD garantiert Eigenschaften bis zu diesem Tag – danach anschauen, riechen, probieren." },
  { id: "k270", f: "Warum müssen Holzbretter nach dem Spülen gut trocknen?", r: "Feuchtigkeit fördert Keime in den Ritzen", x: ["Sonst wird das Holz zu hart", "Sonst verliert das Holz seine Farbe", "Sonst werden die Messer stumpf"], e: "Holzbretter trocken lagern und ab und zu ölen. Tiefe Schnittrillen sind Keimnester – dann abschleifen oder ersetzen." },
  { id: "k271", m: true, f: "Welche Grundsauce steckt in einer Sauce Bercy zu Fisch?", r: "Fisch-Velouté", x: ["Sauce Espagnole", "Sauce Tomate", "Béchamel"], e: "Schalotten und Weißwein reduziert, mit Fisch-Velouté aufgefüllt, mit Butter montiert, dazu Petersilie." },
  { id: "k272", m: true, f: "Wie heißt die provenzalische Knoblauch-Öl-Emulsion?", r: "Aïoli", x: ["Tapenade", "Pistou", "Remoulade"], e: "Ail = Knoblauch, oli = Öl: im Mörser emulgiert, heute meist mit Eigelb." },
  { id: "k273", m: true, f: "Wodurch unterscheidet sich ein Porterhouse- vom T-Bone-Steak?", r: "Es hat einen größeren Filetanteil", x: ["Es stammt aus der Hüfte statt vom Rücken", "Es wird immer ohne Knochen serviert", "Es kommt ausschließlich vom Kalb"], e: "Beide haben den T-förmigen Knochen mit Roastbeef und Filet – beim Porterhouse ist das Filetstück größer." },
  { id: "k274", m: true, f: "Ein „Tomahawk-Steak“ ist …", r: "ein Ribeye mit langem, freigelegtem Knochen", x: ["ein Filetsteak, mit Speck umwickelt", "ein Hüftsteak vom Wagyu am Spieß", "ein Rumpsteak, über Holzfeuer flambiert"], e: "Das Ribeye bleibt am langen Rippenknochen, der sauber geputzt wird („French Trim“)." },
  { id: "k275", m: true, f: "Welches Teilstück vom Rind ist die brasilianische Picanha?", r: "Der Hüftdeckel – bei uns Tafelspitz", x: ["Das Mittelstück des Rinderfilets", "Die Hochrippe mit dem Fettauge", "Das Schaufelstück aus der Schulter"], e: "In Brasilien mit Fettdeckel am Spieß gegrillt; hierzulande wird das Stück meist als Tafelspitz gekocht." },
  { id: "k276", m: true, f: "Wodurch zeichnet sich ein „Fond blanc“ aus?", r: "Knochen und Gemüse werden nicht angeröstet", x: ["Er wird aus gerösteten Knochen mit Tomatenmark gekocht", "Er besteht nur aus Weißwein und Sahne", "Er wird aus weißen Bohnen und Lauch gekocht"], e: "Für helle Saucen wie die Velouté: Kalbs- oder Geflügelknochen blanchiert, nicht geröstet." },
  { id: "k277", m: true, f: "Wie heißt die Fischsauce der thailändischen Küche?", r: "Nam Pla", x: ["Sambal Oelek", "Hoisin", "Sriracha"], e: "Nam Pla: fermentierte Sardellen mit Salz. In Vietnam heißt Fischsauce Nước mắm." },
  { id: "k278", m: true, f: "Welches Enzym in der Kiwi lässt Gelatine nicht fest werden?", r: "Actinidin", x: ["Bromelain", "Papain", "Pepsin"], e: "Wie Bromelain (Ananas) und Papain (Papaya) spaltet Actinidin Eiweiß. Erhitzen zerstört die Enzyme." },
  { id: "k279", m: true, f: "Aus welchem Teil des Schweins wird Coppa gemacht?", r: "Aus dem Nacken", x: ["Aus der Keule", "Aus dem Bauch", "Aus der Backe"], e: "Coppa (Capocollo) ist luftgetrockneter Schweinenacken. Pancetta = Bauch, Guanciale = Backe." },
  { id: "k280", m: true, f: "Welcher Speck gehört in echte Spaghetti alla Carbonara?", r: "Guanciale", x: ["Lardo di Colonnata", "Südtiroler Speck", "Bacon"], e: "Guanciale (Schweinebacke), Eigelb, Pecorino Romano und Pfeffer – ohne Sahne." },
  { id: "k281", m: true, f: "Wofür steht der japanische Begriff „Ikejime“?", r: "Eine stressarme Schlachttechnik für Fisch", x: ["Japanisches Fermentieren von Fisch in Reis", "Hauchdünnes Schneiden von rohem Fisch", "Das Grillen von Aal mit süßer Glasur"], e: "Gehirn und Rückenmark werden schnell durchtrennt – das Fleisch bleibt länger frisch und fest." },
  { id: "k282", m: true, f: "Woraus besteht Nitritpökelsalz?", r: "Speisesalz mit wenig Natriumnitrit", x: ["Meersalz, mit Kräutern versetzt", "Salz, über Buchenholz geräuchert", "Grobes Salz aus dem Toten Meer"], e: "Nitrit sorgt für die rosa Farbe, Pökelaroma und hemmt Keime wie Clostridium botulinum. In Deutschland 0,4–0,5 % Nitrit." },
  { id: "k283", m: true, f: "Was beschreibt die „Retrogradation“ von Stärke?", r: "Sie kristallisiert wieder – Brot wird altbacken", x: ["Sie wird beim Backen zu Zucker umgewandelt", "Sie löst sich in kaltem Wasser vollständig", "Sie bräunt bei hoher Hitze zu Röststoffen"], e: "Verkleisterte Stärke ordnet sich beim Lagern neu – Brot wird hart, Pudding sondert Wasser ab. Kurzes Aufbacken hilft." },
  { id: "k284", m: true, f: "Womit würzten die alten Römer unter dem Namen „Garum“?", r: "Mit fermentierter Fischsauce", x: ["Mit Gewürzwein und Honig", "Mit getrockneten Rosenblüten", "Mit geräuchertem Ziegenkäse"], e: "Fisch und Salz gärten wochenlang in der Sonne – vergleichbar mit heutiger Fischsauce." },
  { id: "k285", m: true, f: "Wer schrieb 1825 die „Physiologie des Geschmacks“?", r: "Jean A. Brillat-Savarin", x: ["Marie-Antoine Carême", "Auguste Escoffier", "Alexandre Dumas der Ältere"], e: "„Sag mir, was du isst, und ich sage dir, wer du bist.“ – nach ihm ist auch der Käse Brillat-Savarin benannt." },
  { id: "k286", m: true, f: "Welcher Restaurantführer vergibt Hauben bzw. Kochmützen?", r: "Gault&Millau", x: ["Guide Michelin", "Varta-Führer", "Der Feinschmecker"], e: "Gault&Millau bewertet mit Punkten und Hauben, der Guide Michelin mit Sternen." },
  { id: "k287", m: true, f: "Ein Michelin-Stern bedeutet laut Guide …", r: "Küche voller Finesse – einen Stopp wert", x: ["Eine Küche, die einen Umweg lohnt", "Eine Küche, die eine eigene Reise wert ist", "Gutes Essen zu einem fairen Preis"], e: "1 Stern: einen Stopp wert, 2 Sterne: einen Umweg wert, 3 Sterne: eine eigene Reise wert. Gut und preiswert: Bib Gourmand." },
  { id: "k288", m: true, f: "Wie heiß sollte der Sud beim Pochieren von Fisch sein?", r: "Etwa 70 bis 80 °C, nicht sprudelnd", x: ["Etwa 40 bis 50 °C, nur lauwarm", "Genau 100 °C, stark sprudelnd", "Etwa 120 °C im Schnellkochtopf"], e: "Knapp unter dem Siedepunkt bleibt der Fisch saftig und zerfällt nicht." },
  { id: "k289", m: true, f: "Welche Säure gibt Sauerkraut seinen Geschmack?", r: "Milchsäure", x: ["Essigsäure", "Zitronensäure", "Weinsäure"], e: "Milchsäurebakterien vergären den Zucker im Kohl – das macht ihn sauer und haltbar." },
  { id: "k290", m: true, f: "Welche Zucker sind die Hauptbestandteile von Honig?", r: "Fruchtzucker und Traubenzucker", x: ["Milchzucker und Malzzucker", "Rohrzucker und Stärke", "Rohrzucker und Maltodextrin"], e: "Honig besteht vor allem aus Fructose und Glucose, dazu etwa 15–20 % Wasser." },
];
